export const HTML: string = "<!doctype html><html><head><meta charset=utf8><meta name=viewport content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><style>:root{color-scheme:light;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}html{scroll-padding-top:env(safe-area-inset-top,0px)}body{margin:0;padding:0;font:14px -apple-system,BlinkMacSystemFont,sans-serif;background:#faf9f5;color:#141413}img{max-width:100%}[hidden]:not([hidden=until-found i]){display:none!important}</style><link rel=\"icon\" type=\"image/png\" href=\"data:image/png;base64,\"></head><body>\n<title>Arquitetura FNI</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap\">\n<style>\n/* Documento técnico na identidade Pró-Frotas: azul de marca para o sistema, laranja só para alertas de ação. */\n:root{\n  --surface-050:#F5F7FA; --surface-000:#FFFFFF; --surface-100:#EAEEF3; --border:#DDE3EA;\n  --ink-900:#12181F; --ink-600:#4B5563; --ink-400:#8A93A3;\n  --brand-600:#0A56C2; --brand-700:#08469E; --brand-050:#EAF2FE; --on-brand:#FFFFFF;\n  --accent-500:#FF7A1A; --accent-050:#FFF1E6;\n  --danger-500:#D63E3E; --danger-050:#FDECEC; --warning-500:#9A6A00; --warning-050:#FBF3DE;\n  --success-500:#1C9A5B; --success-050:#E8F7EF;\n  --sans:\"Inter\",-apple-system,\"Segoe UI\",Roboto,sans-serif;\n  --mono:\"IBM Plex Mono\",ui-monospace,Menlo,Consolas,monospace;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    color-scheme:dark;\n    --surface-050:#0A0D12; --surface-000:#12161C; --surface-100:#1B212A; --border:#262E39;\n    --ink-900:#F4F6F9; --ink-600:#B4BCC8; --ink-400:#7D8796;\n    --brand-600:#4C8DF0; --brand-700:#6BA3F5; --brand-050:#0E2036; --on-brand:#08192E;\n    --accent-500:#FF8A33; --accent-050:#3A2413;\n    --danger-500:#F16060; --danger-050:#331515; --warning-500:#E0A937; --warning-050:#33270B;\n    --success-500:#3FBE7C; --success-050:#0F2A1D;\n  }\n}\n:root[data-theme=\"dark\"]{\n  color-scheme:dark;\n  --surface-050:#0A0D12; --surface-000:#12161C; --surface-100:#1B212A; --border:#262E39;\n  --ink-900:#F4F6F9; --ink-600:#B4BCC8; --ink-400:#7D8796;\n  --brand-600:#4C8DF0; --brand-700:#6BA3F5; --brand-050:#0E2036; --on-brand:#08192E;\n  --accent-500:#FF8A33; --accent-050:#3A2413;\n  --danger-500:#F16060; --danger-050:#331515; --warning-500:#E0A937; --warning-050:#33270B;\n  --success-500:#3FBE7C; --success-050:#0F2A1D;\n}\n*{box-sizing:border-box}\nbody{background:var(--surface-050);color:var(--ink-900);font-family:var(--sans);font-size:15px;line-height:1.6;margin:0}\n.wrap{max-width:1080px;margin:0 auto;padding-inline:20px;padding-block:32px 80px}\nh1,h2,h3{text-wrap:balance;line-height:1.2;margin:0}\nh1{font-size:34px;font-weight:700;letter-spacing:-.01em}\nh2{font-size:24px;font-weight:700}\nh3{font-size:17px;font-weight:600}\np{margin:0;max-width:68ch}\ncode,.mono{font-family:var(--mono);font-size:.88em}\ncode{background:var(--surface-100);padding:1px 5px;border-radius:5px}\na{color:var(--brand-600)}\n:focus-visible{outline:2px solid var(--brand-600);outline-offset:2px}\n.eyebrow{font-family:var(--mono);font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--brand-600)}\nheader.top{display:flex;flex-direction:column;gap:12px;padding-block:8px 24px}\n.lead{font-size:17px;color:var(--ink-600)}\n.meta{font-size:13px;color:var(--ink-400)}\n.facts{display:flex;flex-wrap:wrap;gap:8px 22px;margin-top:6px;font-size:14px;color:var(--ink-600)}\n.facts b{color:var(--ink-900);font-variant-numeric:tabular-nums;font-weight:600}\nnav.levels{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:var(--surface-050);border-bottom:1px solid var(--border);margin-inline:-20px;padding-inline:20px}\nnav.levels ul{list-style:none;margin:0;padding:10px 0;display:flex;gap:6px;overflow-x:auto}\nnav.levels a{display:inline-flex;gap:6px;align-items:baseline;white-space:nowrap;text-decoration:none;color:var(--ink-600);font-size:14px;font-weight:500;padding:6px 12px;border-radius:999px}\nnav.levels a span{font-family:var(--mono);font-size:11px;color:var(--ink-400)}\nnav.levels a:hover{background:var(--surface-100);color:var(--ink-900)}\nsection{padding-top:44px;display:flex;flex-direction:column;gap:14px;scroll-margin-top:56px}\n.sec-head{display:flex;flex-direction:column;gap:6px}\n.legend{display:flex;flex-wrap:wrap;gap:10px 18px;font-size:13px;color:var(--ink-600);margin-top:4px}\n.legend i{display:inline-block;width:22px;height:13px;border-radius:4px;margin-right:6px;vertical-align:-2px;border:1.5px solid}\n.lg-person{background:var(--brand-050);border-color:var(--brand-600)!important;border-radius:7px!important}\n.lg-system{background:var(--brand-600);border-color:var(--brand-700)!important}\n.lg-container{background:var(--surface-000);border-color:var(--brand-600)!important}\n.lg-db{background:var(--brand-050);border-color:var(--brand-700)!important}\n.lg-ext{background:var(--surface-100);border-color:var(--ink-400)!important}\n.lg-legacy{background:var(--warning-050);border-color:var(--warning-500)!important;border-style:dashed!important}\nfigure{margin:0;background:var(--surface-000);border:1px solid var(--border);border-radius:14px;overflow-x:auto}\nfigure svg{display:block;width:100%;min-width:860px;height:auto;padding:10px}\nfigcaption{font-size:13px;color:var(--ink-400);padding:0 16px 12px}\n/* diagramas */\n.n rect{stroke-width:1.5}\n.n-person rect{fill:var(--brand-050);stroke:var(--brand-600)}\n.n-system rect{fill:var(--brand-600);stroke:var(--brand-700)}\n.n-container rect{fill:var(--surface-000);stroke:var(--brand-600)}\n.n-db rect{fill:var(--brand-050);stroke:var(--brand-700)}\n.n-ext rect{fill:var(--surface-100);stroke:var(--ink-400)}\n.n-legacy rect{fill:var(--warning-050);stroke:var(--warning-500)}\n.t-name{font:600 14px var(--sans);fill:var(--ink-900)}\n.t-tech{font:400 11px var(--mono);fill:var(--ink-600)}\n.t-desc{font:400 12px var(--sans);fill:var(--ink-600)}\n.n-system .t-name,.n-system .t-tech,.n-system .t-desc{fill:var(--on-brand)}\n.n-system .t-name{font-size:17px}\n.b rect{fill:none;stroke:var(--ink-400);stroke-width:1;stroke-dasharray:6 5}\n.t-bound{font:600 13px var(--sans);fill:var(--ink-600)}\n.t-boundsub{font:400 11px var(--mono);fill:var(--ink-400)}\n.rel{fill:none;stroke:var(--ink-600);stroke-width:1.3}\n.ahead{fill:none;stroke:var(--ink-600);stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}\n.t-rel,.t-step{font:400 11.5px var(--sans);fill:var(--ink-600);paint-order:stroke;stroke:var(--surface-000);stroke-width:4px;stroke-linejoin:round}\n.t-step{font-family:var(--mono);font-size:11px;fill:var(--ink-900)}\n.life{stroke:var(--border);stroke-width:1.5;stroke-dasharray:4 4}\n/* listas de elementos */\n.elements{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 28px;margin-top:4px}\n.el{display:grid;grid-template-columns:150px minmax(0,1fr);gap:12px;padding:10px 0;border-top:1px solid var(--border);font-size:14px}\n.el dt{font-weight:600}\n.el dd{margin:0;color:var(--ink-600)}\n/* tabela */\n.table-wrap{overflow-x:auto;background:var(--surface-000);border:1px solid var(--border);border-radius:14px}\ntable{border-collapse:collapse;width:100%;min-width:640px;font-size:14px}\nth{text-align:left;font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-400);font-weight:600;padding:10px 14px;border-bottom:1px solid var(--border)}\ntd{padding:9px 14px;border-bottom:1px solid var(--border);vertical-align:top}\ntr:last-child td{border-bottom:0}\ntr.grp td{background:var(--surface-100);font-weight:600;font-size:13px}\ntd.when{white-space:nowrap;font-variant-numeric:tabular-nums;color:var(--ink-600)}\n/* achados */\n.findings{display:flex;flex-direction:column;gap:0;background:var(--surface-000);border:1px solid var(--border);border-radius:14px}\n.f{display:grid;grid-template-columns:96px minmax(0,1fr);gap:16px;padding:16px 18px;border-top:1px solid var(--border)}\n.f:first-child{border-top:0}\n.f h3{margin-bottom:4px}\n.f p{color:var(--ink-600);font-size:14px}\n.f p+p{margin-top:6px}\n.f .acao{color:var(--ink-900)}\n.sev{align-self:start;display:inline-block;font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;padding:3px 9px;border-radius:999px;text-align:center}\n.sev-alta{background:var(--danger-050);color:var(--danger-500)}\n.sev-media{background:var(--warning-050);color:var(--warning-500)}\n.sev-baixa{background:var(--surface-100);color:var(--ink-600)}\n.sev-forte{background:var(--success-050);color:var(--success-500)}\n.status{display:inline-block;margin-left:8px;font-size:12px;font-weight:600;color:var(--success-500)}\n.status.pend{color:var(--warning-500)}\nfooter{margin-top:48px;font-size:13px;color:var(--ink-400)}\n@media (max-width:760px){\n  h1{font-size:27px}\n  .elements{grid-template-columns:minmax(0,1fr)}\n  .el{grid-template-columns:120px minmax(0,1fr)}\n  .f{grid-template-columns:minmax(0,1fr);gap:8px}\n}\n@media (prefers-reduced-motion:no-preference){html{scroll-behavior:smooth}}\n.logo-fni{display:block;align-self:flex-start;height:54px;width:auto;max-width:none;object-fit:contain;flex:none;background:#fff;border-radius:10px;padding:6px 12px;box-shadow:0 1px 3px rgba(0,0,0,.18);margin:0 0 14px}\n</style>\n\n<div class=\"wrap\">\n  <header class=\"top\">\n    <img class=\"logo-fni\" alt=\"FNI — Fleet Network Intelligence\" src=\"data:image/png;base64,\">\n    <span class=\"eyebrow\">Arquitetura de software · modelo C4</span>\n    <h1>Arquitetura FNI</h1>\n    <p class=\"lead\">Do contexto de negócio até o código, em quatro níveis de zoom, mais um recorte completo do PDV FNI. Cada nível mostra só o que importa naquela distância: quem usa o sistema, quais aplicações rodam, como o Web app se organiza por dentro e, por fim, um fluxo real no código.</p>\n    <p class=\"meta\">Levantado em 1 de outubro de 2026 a partir do código dos repositórios <code>gestao-frotas-web</code> e <code>estudo-de-rede</code>, do banco Supabase e da configuração do Railway. Complementado de 3 a 5 de outubro de 2026 (resgate de pontos, orientação de NF-e, menu lateral, tema claro/escuro e Pré-Pedido liberado pelo OTP rotativo do motorista, aviso de Pré-Pedido fora do PDV e pedidos de ajuste, incluídos) com o PDV FNI (repositório <code>pdv-fni</code>), descrito na seção <a href=\"#pdv\">PDV FNI</a>. Mudanças em <a href=\"#historico\">Histórico de ajustes</a>.</p>\n    <div class=\"facts\">\n      <span><b>96</b> módulos no painel</span>\n      <span><b>49</b> rotas de API</span>\n      <span><b>192</b> tabelas, todas com RLS</span>\n      <span><b>4</b> aplicações no Railway</span>\n      <span><b>25</b> rotinas agendadas</span>\n      <span><b>22</b> Edge Functions</span>\n    </div>\n  </header>\n\n  <nav class=\"levels\" aria-label=\"Níveis do modelo\">\n    <ul>\n      <li><a href=\"#contexto\"><span>1</span>Contexto</a></li>\n      <li><a href=\"#containers\"><span>2</span>Containers</a></li>\n      <li><a href=\"#componentes\"><span>3</span>Componentes</a></li>\n      <li><a href=\"#codigo\"><span>4</span>Código</a></li>\n      <li><a href=\"#pdv\"><span>◆</span>PDV FNI</a></li>\n      <li><a href=\"#rotinas\"><span>+</span>Rotinas agendadas</a></li>\n      <li><a href=\"#achados\"><span>!</span>Achados</a></li>\n      <li><a href=\"#historico\"><span>✓</span>Histórico de ajustes</a></li>\n    </ul>\n  </nav>\n\n  <section aria-label=\"Notação\">\n    <div class=\"legend\">\n      <span><i class=\"lg-person\"></i>Pessoa</span>\n      <span><i class=\"lg-system\"></i>Sistema FNI</span>\n      <span><i class=\"lg-container\"></i>Container ou componente</span>\n      <span><i class=\"lg-db\"></i>Dados e agendamento</span>\n      <span><i class=\"lg-ext\"></i>Sistema externo</span>\n      <span><i class=\"lg-legacy\"></i>Legado</span>\n    </div>\n  </section>\n\n  <section id=\"contexto\">\n    <div class=\"sec-head\">\n      <span class=\"eyebrow\">Nível 1</span>\n      <h2>Contexto do sistema</h2>\n      <p>O FNI é um único sistema na visão do negócio. Seis perfis de pessoas o usam, cada um com sua trilha de telas e permissões, e ele conversa com dez grupos de sistemas externos.</p>\n    </div>\n    <figure><svg viewBox=\"0 0 1000 624\" role=\"img\" aria-labelledby=\"t-Nível \"><title>Nível 1: contexto do FNI</title><desc>Seis perfis de pessoas usam o FNI, que se integra a dez sistemas externos.</desc><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M1 1L9 5L1 9\" class=\"ahead\"/></marker></defs><g class=\"n n-person\">\n<rect x=\"20\" y=\"20\" width=\"150\" height=\"104\" rx=\"14\"/>\n<text class=\"t-name\" x=\"95.0\" y=\"39.5\" text-anchor=\"middle\">Gestor de frota</text>\n<text class=\"t-tech\" x=\"95.0\" y=\"56.5\" text-anchor=\"middle\">[Pessoa]</text>\n<text class=\"t-desc\" x=\"95.0\" y=\"71.5\" text-anchor=\"middle\">Acompanha custos,</text>\n<text class=\"t-desc\" x=\"95.0\" y=\"86.5\" text-anchor=\"middle\">abastecimentos e frota;</text>\n<text class=\"t-desc\" x=\"95.0\" y=\"101.5\" text-anchor=\"middle\">pode ver o grupo</text>\n<text class=\"t-desc\" x=\"95.0\" y=\"116.5\" text-anchor=\"middle\">econômico</text>\n</g>\n<path class=\"rel\" d=\"M95 124 L350 198\" marker-end=\"url(#ah)\"/>\n<text class=\"t-rel\" x=\"222\" y=\"166\" text-anchor=\"middle\">Usa no navegador</text>\n<g class=\"n n-person\">\n<rect x=\"182\" y=\"20\" width=\"150\" height=\"104\" rx=\"14\"/>\n<text class=\"t-name\" x=\"257.0\" y=\"47.0\" text-anchor=\"middle\">Motorista</text>\n<text class=\"t-tech\" x=\"257.0\" y=\"64.0\" text-anchor=\"middle\">[Pessoa]</text>\n<text class=\"t-desc\" x=\"257.0\" y=\"79.0\" text-anchor=\"middle\">Abastece, faz checklist</text>\n<text class=\"t-desc\" x=\"257.0\" y=\"94.0\" text-anchor=\"middle\">e registra ocorrências</text>\n<text class=\"t-desc\" x=\"257.0\" y=\"109.0\" text-anchor=\"middle\">no celular</text>\n</g>\n<path class=\"rel\" d=\"M257 124 L410 198\" marker-end=\"url(#ah)\"/>\n<text class=\"t-rel\" x=\"333\" y=\"166\" text-anchor=\"middle\">Usa no celular</text>\n<g class=\"n n-person\">\n<rect x=\"344\" y=\"20\" width=\"150\" height=\"104\" rx=\"14\"/>\n<text class=\"t-name\" x=\"419.0\" y=\"47.0\" text-anchor=\"middle\">Posto ou revenda</text>\n<text class=\"t-tech\" x=\"419.0\" y=\"64.0\" text-anchor=\"middle\">[Pessoa]</text>\n<text class=\"t-desc\" x=\"419.0\" y=\"79.0\" text-anchor=\"middle\">Gerencia preços,</text>\n<text class=\"t-desc\" x=\"419.0\" y=\"94.0\" text-anchor=\"middle\">acordos, faturas e</text>\n<text class=\"t-desc\" x=\"419.0\" y=\"109.0\" text-anchor=\"middle\">clientes</text>\n</g>\n<path class=\"rel\" d=\"M419 124 L470 198\" marker-end=\"url(#ah)\"/>\n<text class=\"t-rel\" x=\"444\" y=\"166\" text-anchor=\"middle\">Usa no navegador</text>\n<g class=\"n n-person\">\n<rect x=\"506\" y=\"20\" width=\"150\" height=\"104\" rx=\"14\"/>\n<text class=\"t-name\" x=\"581.0\" y=\"47.0\" text-anchor=\"middle\">Frentista ou caixa</text>\n<text class=\"t-tech\" x=\"581.0\" y=\"64.0\" text-anchor=\"middle\">[Pessoa]</text>\n<text class=\"t-desc\" x=\"581.0\" y=\"79.0\" text-anchor=\"middle\">Opera o PDV FNI no</text>\n<text class=\"t-desc\" x=\"581.0\" y=\"94.0\" text-anchor=\"middle\">balcão e na pista:</text>\n<text class=\"t-desc\" x=\"581.0\" y=\"109.0\" text-anchor=\"middle\">bombas e abastecimentos</text>\n</g>\n<path class=\"rel\" d=\"M581 124 L530 198\" marker-end=\"url(#ah)\"/>\n<text class=\"t-rel\" x=\"555\" y=\"166\" text-anchor=\"middle\">Opera o PDV</text>\n<g class=\"n n-person\">\n<rect x=\"668\" y=\"20\" width=\"150\" height=\"104\" rx=\"14\"/>\n<text class=\"t-name\" x=\"743.0\" y=\"54.5\" text-anchor=\"middle\">Equipe FNI</text>\n<text class=\"t-tech\" x=\"743.0\" y=\"71.5\" text-anchor=\"middle\">[Pessoa]</text>\n<text class=\"t-desc\" x=\"743.0\" y=\"86.5\" text-anchor=\"middle\">Administradores que</text>\n<text class=\"t-desc\" x=\"743.0\" y=\"101.5\" text-anchor=\"middle\">operam a plataforma</text>\n</g>\n<path class=\"rel\" d=\"M743 124 L590 198\" marker-end=\"url(#ah)\"/>\n<text class=\"t-rel\" x=\"666\" y=\"166\" text-anchor=\"middle\">Opera e atende</text>\n<g class=\"n n-person\">\n<rect x=\"830\" y=\"20\" width=\"150\" height=\"104\" rx=\"14\"/>\n<text class=\"t-name\" x=\"905.0\" y=\"47.0\" text-anchor=\"middle\">Visitante ou lead</text>\n<text class=\"t-tech\" x=\"905.0\" y=\"64.0\" text-anchor=\"middle\">[Pessoa]</text>\n<text class=\"t-desc\" x=\"905.0\" y=\"79.0\" text-anchor=\"middle\">Conhece o produto,</text>\n<text class=\"t-desc\" x=\"905.0\" y=\"94.0\" text-anchor=\"middle\">testa a demo e assina</text>\n<text class=\"t-desc\" x=\"905.0\" y=\"109.0\" text-anchor=\"middle\">um plano</text>\n</g>\n<path class=\"rel\" d=\"M905 124 L650 198\" marker-end=\"url(#ah)\"/>\n<text class=\"t-rel\" x=\"777\" y=\"166\" text-anchor=\"middle\">Navega e assina</text>\n<g class=\"n n-system\">\n<rect x=\"290\" y=\"200\" width=\"420\" height=\"112\" rx=\"8\"/>\n<text class=\"t-name\" x=\"500.0\" y=\"238.5\" text-anchor=\"middle\">FNI</text>\n<text class=\"t-tech\" x=\"500.0\" y=\"255.5\" text-anchor=\"middle\">[Sistema de software]</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"270.5\" text-anchor=\"middle\">Gestão de frotas multiempresa: combustível, rede de postos,</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"285.5\" text-anchor=\"middle\">fretes, manutenção, financeiro e ponto de venda (PDV)</text>\n</g>\n<g class=\"b\"><rect x=\"10\" y=\"372\" width=\"980\" height=\"236\" rx=\"12\"/>\n<text class=\"t-bound\" x=\"24\" y=\"392\">Sistemas externos</text>\n</g>\n<path class=\"rel\" d=\"M500 314 L500 370\" marker-end=\"url(#ah)\" marker-start=\"url(#ah)\"/><text class=\"t-rel\" x=\"512\" y=\"336\" text-anchor=\"start\">Troca dados por APIs HTTPS,</text><text class=\"t-rel\" x=\"512\" y=\"350\" text-anchor=\"start\">webhooks e e-mail</text>\n<g class=\"n n-ext\">\n<rect x=\"20\" y=\"412\" width=\"180\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"110.0\" y=\"433.0\" text-anchor=\"middle\">Provedores e ERPs</text>\n<text class=\"t-desc\" x=\"110.0\" y=\"454.0\" text-anchor=\"middle\">Veloe, TicketLog,</text>\n<text class=\"t-desc\" x=\"110.0\" y=\"469.0\" text-anchor=\"middle\">Valecard, RedeFrota,</text>\n<text class=\"t-desc\" x=\"110.0\" y=\"484.0\" text-anchor=\"middle\">TOTVS, SAP</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"215\" y=\"412\" width=\"180\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"305.0\" y=\"433.0\" text-anchor=\"middle\">ProFrotas</text>\n<text class=\"t-desc\" x=\"305.0\" y=\"454.0\" text-anchor=\"middle\">API de abastecimentos,</text>\n<text class=\"t-desc\" x=\"305.0\" y=\"469.0\" text-anchor=\"middle\">sincronizada de hora em</text>\n<text class=\"t-desc\" x=\"305.0\" y=\"484.0\" text-anchor=\"middle\">hora</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"410\" y=\"412\" width=\"180\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"500.0\" y=\"433.0\" text-anchor=\"middle\">ANP e Base dos Dados</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"454.0\" text-anchor=\"middle\">Preços oficiais de</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"469.0\" text-anchor=\"middle\">combustível e cadastro</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"484.0\" text-anchor=\"middle\">de postos</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"605\" y=\"412\" width=\"180\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"695.0\" y=\"440.5\" text-anchor=\"middle\">Tabela FIPE</text>\n<text class=\"t-desc\" x=\"695.0\" y=\"461.5\" text-anchor=\"middle\">Valor de mercado dos</text>\n<text class=\"t-desc\" x=\"695.0\" y=\"476.5\" text-anchor=\"middle\">veículos, todo mês</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"800\" y=\"412\" width=\"180\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"890.0\" y=\"440.5\" text-anchor=\"middle\">Stripe</text>\n<text class=\"t-desc\" x=\"890.0\" y=\"461.5\" text-anchor=\"middle\">Checkout, assinaturas e</text>\n<text class=\"t-desc\" x=\"890.0\" y=\"476.5\" text-anchor=\"middle\">portal de cobrança</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"20\" y=\"506\" width=\"180\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"110.0\" y=\"534.5\" text-anchor=\"middle\">Anthropic Claude</text>\n<text class=\"t-desc\" x=\"110.0\" y=\"555.5\" text-anchor=\"middle\">Assistente IA e</text>\n<text class=\"t-desc\" x=\"110.0\" y=\"570.5\" text-anchor=\"middle\">insights diários</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"215\" y=\"506\" width=\"180\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"305.0\" y=\"534.5\" text-anchor=\"middle\">Resend</text>\n<text class=\"t-desc\" x=\"305.0\" y=\"555.5\" text-anchor=\"middle\">E-mails de alertas,</text>\n<text class=\"t-desc\" x=\"305.0\" y=\"570.5\" text-anchor=\"middle\">trials e negociações</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"410\" y=\"506\" width=\"180\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"500.0\" y=\"527.0\" text-anchor=\"middle\">Mapas</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"548.0\" text-anchor=\"middle\">OpenStreetMap, OSRM e</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"563.0\" text-anchor=\"middle\">Nominatim para rotas e</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"578.0\" text-anchor=\"middle\">endereços</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"605\" y=\"506\" width=\"180\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"695.0\" y=\"542.0\" text-anchor=\"middle\">Google</text>\n<text class=\"t-desc\" x=\"695.0\" y=\"563.0\" text-anchor=\"middle\">Login com conta Google</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"800\" y=\"506\" width=\"180\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"890.0\" y=\"527.0\" text-anchor=\"middle\">Monitoramento</text>\n<text class=\"t-desc\" x=\"890.0\" y=\"548.0\" text-anchor=\"middle\">Sentry, Hotjar,</text>\n<text class=\"t-desc\" x=\"890.0\" y=\"563.0\" text-anchor=\"middle\">UptimeRobot e Microsoft</text>\n<text class=\"t-desc\" x=\"890.0\" y=\"578.0\" text-anchor=\"middle\">Teams</text>\n</g></svg></figure>\n    <dl class=\"elements\">\n      <div class=\"el\"><dt>Gestor de frota</dt><dd>Perfil <code>gestor_frota</code> e a equipe que ele convida, que entra como <code>analista</code>. Vê as empresas em que está cadastrado e, quando há grupo econômico ativo, todas as empresas do grupo.</dd></div>\n      <div class=\"el\"><dt>Motorista</dt><dd>Entra pelo PWA com usuário derivado do celular. Registra abastecimentos internos, checklists e ocorrências.</dd></div>\n      <div class=\"el\"><dt>Posto ou revenda</dt><dd>Perfil <code>posto</code>, com menu próprio: preços, acordos, faturas, clientes e inteligência comercial.</dd></div>\n      <div class=\"el\"><dt>Frentista ou caixa</dt><dd>Usa o PDV FNI com a mesma conta <code>posto</code>: escolhe o bico, valida o código do motorista, conclui o abastecimento e fecha o caixa do turno pelo dashboard.</dd></div>\n      <div class=\"el\"><dt>Equipe FNI</dt><dd>Perfil <code>admin</code>. Enxerga todos os clientes e escolhe o cliente atual pelo menu. O <code>analista</code> deixou de ser da equipe FNI: é o perfil de equipe do cliente e perdeu os poderes globais (ler todos os usuários, gerenciar usuários de qualquer empresa e visão global de badges).</dd></div>\n      <div class=\"el\"><dt>Provedores e ERPs</dt><dd>Enviam abastecimentos, custos, notas e parâmetros pela API de integrações, autenticados por chave de API da empresa.</dd></div>\n      <div class=\"el\"><dt>ProFrotas</dt><dd>Única integração em que o FNI busca os dados: sincronização de hora em hora em <code>api-portal.profrotas.com.br</code>.</dd></div>\n    </dl>\n  </section>\n\n  <section id=\"containers\">\n    <div class=\"sec-head\">\n      <span class=\"eyebrow\">Nível 2</span>\n      <h2>Containers</h2>\n      <p>Por dentro, o FNI é formado por quatro aplicações ativas no Railway e pelo Supabase, que concentra dados, login, eventos ao vivo, arquivos e rotinas. As quatro aplicações falam direto com o banco, e a separação entre clientes é garantida pelo próprio banco (RLS), não pelo código de cada app.</p>\n    </div>\n    <figure><svg viewBox=\"0 0 1000 736\" role=\"img\" aria-labelledby=\"t-Nível \"><title>Nível 2: containers do FNI</title><desc>Web app Next.js, PDV Next.js, dois PWAs Flutter e o legado Python rodam no Railway; todos usam o Supabase em São Paulo.</desc><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M1 1L9 5L1 9\" class=\"ahead\"/></marker></defs><g class=\"n n-person\">\n<rect x=\"20\" y=\"16\" width=\"180\" height=\"58\" rx=\"14\"/>\n<text class=\"t-name\" x=\"110.0\" y=\"42.5\" text-anchor=\"middle\">Gestores e equipe FNI</text>\n<text class=\"t-tech\" x=\"110.0\" y=\"59.5\" text-anchor=\"middle\">[Pessoa · navegador]</text>\n</g>\n<g class=\"n n-person\">\n<rect x=\"215\" y=\"16\" width=\"180\" height=\"58\" rx=\"14\"/>\n<text class=\"t-name\" x=\"305.0\" y=\"42.5\" text-anchor=\"middle\">Visitantes e leads</text>\n<text class=\"t-tech\" x=\"305.0\" y=\"59.5\" text-anchor=\"middle\">[Pessoa · navegador]</text>\n</g>\n<g class=\"n n-person\">\n<rect x=\"410\" y=\"16\" width=\"180\" height=\"58\" rx=\"14\"/>\n<text class=\"t-name\" x=\"500.0\" y=\"42.5\" text-anchor=\"middle\">Motoristas</text>\n<text class=\"t-tech\" x=\"500.0\" y=\"59.5\" text-anchor=\"middle\">[Pessoa · celular]</text>\n</g>\n<g class=\"n n-person\">\n<rect x=\"605\" y=\"16\" width=\"180\" height=\"58\" rx=\"14\"/>\n<text class=\"t-name\" x=\"695.0\" y=\"42.5\" text-anchor=\"middle\">Gestores no celular</text>\n<text class=\"t-tech\" x=\"695.0\" y=\"59.5\" text-anchor=\"middle\">[Pessoa · celular]</text>\n</g>\n<g class=\"n n-person\">\n<rect x=\"800\" y=\"16\" width=\"180\" height=\"58\" rx=\"14\"/>\n<text class=\"t-name\" x=\"890.0\" y=\"42.5\" text-anchor=\"middle\">Frentistas e caixas</text>\n<text class=\"t-tech\" x=\"890.0\" y=\"59.5\" text-anchor=\"middle\">[Pessoa · navegador]</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"20\" y=\"104\" width=\"960\" height=\"38\" rx=\"8\"/>\n<text class=\"t-name\" x=\"500.0\" y=\"129.0\" text-anchor=\"middle\">Cloudflare · DNS, TLS e proteção do domínio</text>\n</g>\n<path class=\"rel\" d=\"M110 74 L110 102\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M305 74 L305 102\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M500 74 L500 102\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M695 74 L695 102\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M890 74 L890 102\" marker-end=\"url(#ah)\"/>\n<g class=\"b\"><rect x=\"10\" y=\"166\" width=\"980\" height=\"470\" rx=\"12\"/>\n<text class=\"t-bound\" x=\"24\" y=\"186\">FNI</text>\n<text class=\"t-boundsub\" x=\"24\" y=\"202\">Sistema de software · apps no Railway us-east4 (Virgínia, EUA)</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"30\" y=\"214\" width=\"220\" height=\"116\" rx=\"8\"/>\n<text class=\"t-name\" x=\"140.0\" y=\"247.0\" text-anchor=\"middle\">Web app</text>\n<text class=\"t-tech\" x=\"140.0\" y=\"264.0\" text-anchor=\"middle\">[Next.js 15 · Railway]</text>\n<text class=\"t-desc\" x=\"140.0\" y=\"279.0\" text-anchor=\"middle\">fxgestaodefrotasonline.com</text>\n<text class=\"t-desc\" x=\"140.0\" y=\"294.0\" text-anchor=\"middle\">Painel, landing, demo, API de</text>\n<text class=\"t-desc\" x=\"140.0\" y=\"309.0\" text-anchor=\"middle\">integrações e rotinas</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"262\" y=\"214\" width=\"180\" height=\"116\" rx=\"8\"/>\n<text class=\"t-name\" x=\"352.0\" y=\"247.0\" text-anchor=\"middle\">PWA do motorista</text>\n<text class=\"t-tech\" x=\"352.0\" y=\"264.0\" text-anchor=\"middle\">[Flutter Web · Railway]</text>\n<text class=\"t-desc\" x=\"352.0\" y=\"279.0\" text-anchor=\"middle\">estrada.fxgestaodefrotas…</text>\n<text class=\"t-desc\" x=\"352.0\" y=\"294.0\" text-anchor=\"middle\">Abastecimento, checklist e</text>\n<text class=\"t-desc\" x=\"352.0\" y=\"309.0\" text-anchor=\"middle\">avaliação do posto</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"454\" y=\"214\" width=\"180\" height=\"116\" rx=\"8\"/>\n<text class=\"t-name\" x=\"544.0\" y=\"247.0\" text-anchor=\"middle\">PWA do gestor</text>\n<text class=\"t-tech\" x=\"544.0\" y=\"264.0\" text-anchor=\"middle\">[Flutter Web · Railway]</text>\n<text class=\"t-desc\" x=\"544.0\" y=\"279.0\" text-anchor=\"middle\">mobile.fxgestaodefrotas…</text>\n<text class=\"t-desc\" x=\"544.0\" y=\"294.0\" text-anchor=\"middle\">Painel mobile; negados do</text>\n<text class=\"t-desc\" x=\"544.0\" y=\"309.0\" text-anchor=\"middle\">PDV e Veículos ao vivo</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"646\" y=\"214\" width=\"180\" height=\"116\" rx=\"8\"/>\n<text class=\"t-name\" x=\"736.0\" y=\"247.0\" text-anchor=\"middle\">PDV FNI</text>\n<text class=\"t-tech\" x=\"736.0\" y=\"264.0\" text-anchor=\"middle\">[Next.js 15 · Railway]</text>\n<text class=\"t-desc\" x=\"736.0\" y=\"279.0\" text-anchor=\"middle\">pdv.fxgestaodefrotas…</text>\n<text class=\"t-desc\" x=\"736.0\" y=\"294.0\" text-anchor=\"middle\">Caixa do posto: bombas,</text>\n<text class=\"t-desc\" x=\"736.0\" y=\"309.0\" text-anchor=\"middle\">bicos, extrato e dashboard</text>\n</g>\n<g class=\"n n-legacy\">\n<rect x=\"838\" y=\"214\" width=\"132\" height=\"116\" rx=\"8\" stroke-dasharray=\"6 4\"/>\n<text class=\"t-name\" x=\"904.0\" y=\"247.0\" text-anchor=\"middle\">Legado Python</text>\n<text class=\"t-tech\" x=\"904.0\" y=\"264.0\" text-anchor=\"middle\">[Python · Railway]</text>\n<text class=\"t-desc\" x=\"904.0\" y=\"279.0\" text-anchor=\"middle\">Streamlit e FastAPI.</text>\n<text class=\"t-desc\" x=\"904.0\" y=\"294.0\" text-anchor=\"middle\">Nenhum app depende;</text>\n<text class=\"t-desc\" x=\"904.0\" y=\"309.0\" text-anchor=\"middle\">aguarda desligamento</text>\n</g>\n<path class=\"rel\" d=\"M140 142 L140 212\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M352 142 L352 212\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M544 142 L544 212\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M736 142 L736 212\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M904 142 L904 212\" marker-end=\"url(#ah)\"/>\n<text class=\"t-rel\" x=\"150\" y=\"182\" text-anchor=\"start\">HTTPS</text>\n<g class=\"b\"><rect x=\"30\" y=\"372\" width=\"940\" height=\"244\" rx=\"12\"/>\n<text class=\"t-bound\" x=\"44\" y=\"392\">Supabase</text>\n<text class=\"t-boundsub\" x=\"44\" y=\"408\">Região São Paulo (sa-east-1) · PostgreSQL 17</text>\n</g>\n<g class=\"n n-db\">\n<rect x=\"50\" y=\"420\" width=\"210\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"155.0\" y=\"437.5\" text-anchor=\"middle\">PostgreSQL</text>\n<text class=\"t-tech\" x=\"155.0\" y=\"454.5\" text-anchor=\"middle\">[banco de dados]</text>\n<text class=\"t-desc\" x=\"155.0\" y=\"473.5\" text-anchor=\"middle\">192 tabelas, todas com RLS</text>\n<text class=\"t-desc\" x=\"155.0\" y=\"488.5\" text-anchor=\"middle\">por empresa; 373 funções; 4</text>\n<text class=\"t-desc\" x=\"155.0\" y=\"503.5\" text-anchor=\"middle\">views</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"275\" y=\"420\" width=\"160\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"355.0\" y=\"445.0\" text-anchor=\"middle\">Auth</text>\n<text class=\"t-tech\" x=\"355.0\" y=\"462.0\" text-anchor=\"middle\">[Supabase Auth]</text>\n<text class=\"t-desc\" x=\"355.0\" y=\"481.0\" text-anchor=\"middle\">E-mail e senha,</text>\n<text class=\"t-desc\" x=\"355.0\" y=\"496.0\" text-anchor=\"middle\">Google e MFA</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"450\" y=\"420\" width=\"160\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"530.0\" y=\"445.0\" text-anchor=\"middle\">Realtime</text>\n<text class=\"t-tech\" x=\"530.0\" y=\"462.0\" text-anchor=\"middle\">[Supabase Realtime]</text>\n<text class=\"t-desc\" x=\"530.0\" y=\"481.0\" text-anchor=\"middle\">10 tabelas publicadas</text>\n<text class=\"t-desc\" x=\"530.0\" y=\"496.0\" text-anchor=\"middle\">para eventos ao vivo</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"625\" y=\"420\" width=\"160\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"705.0\" y=\"445.0\" text-anchor=\"middle\">Storage</text>\n<text class=\"t-tech\" x=\"705.0\" y=\"462.0\" text-anchor=\"middle\">[Supabase Storage]</text>\n<text class=\"t-desc\" x=\"705.0\" y=\"481.0\" text-anchor=\"middle\">13 buckets: anexos,</text>\n<text class=\"t-desc\" x=\"705.0\" y=\"496.0\" text-anchor=\"middle\">XML, evidências</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"800\" y=\"420\" width=\"150\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"875.0\" y=\"437.5\" text-anchor=\"middle\">Edge Functions</text>\n<text class=\"t-tech\" x=\"875.0\" y=\"454.5\" text-anchor=\"middle\">[Deno]</text>\n<text class=\"t-desc\" x=\"875.0\" y=\"473.5\" text-anchor=\"middle\">21 funções: Stripe,</text>\n<text class=\"t-desc\" x=\"875.0\" y=\"488.5\" text-anchor=\"middle\">e-mails, alertas,</text>\n<text class=\"t-desc\" x=\"875.0\" y=\"503.5\" text-anchor=\"middle\">ANP</text>\n</g>\n<g class=\"n n-db\">\n<rect x=\"50\" y=\"528\" width=\"210\" height=\"72\" rx=\"8\"/>\n<text class=\"t-name\" x=\"155.0\" y=\"543.0\" text-anchor=\"middle\">Agendador</text>\n<text class=\"t-tech\" x=\"155.0\" y=\"560.0\" text-anchor=\"middle\">[pg_cron · pg_net]</text>\n<text class=\"t-desc\" x=\"155.0\" y=\"579.0\" text-anchor=\"middle\">25 rotinas no banco, no app</text>\n<text class=\"t-desc\" x=\"155.0\" y=\"594.0\" text-anchor=\"middle\">e nas funções</text>\n</g>\n<path class=\"rel\" d=\"M140 332 L140 418\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"148\" y=\"372\" text-anchor=\"start\">Lê e grava</text><text class=\"t-rel\" x=\"148\" y=\"386\" text-anchor=\"start\">com RLS</text>\n<path class=\"rel\" d=\"M230 332 L480 418\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"372\" y=\"386\" text-anchor=\"end\">Escuta eventos</text>\n<path class=\"rel\" d=\"M352 332 L352 370\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"360\" y=\"356\" text-anchor=\"start\">SDK Supabase</text>\n<path class=\"rel\" d=\"M544 332 L544 370\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"552\" y=\"356\" text-anchor=\"start\">SDK Supabase</text>\n<path class=\"rel\" d=\"M736 332 L736 370\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"744\" y=\"356\" text-anchor=\"start\">SDK Supabase + RPCs</text>\n<path class=\"rel\" d=\"M904 332 L904 370\" stroke-dasharray=\"5 4\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"912\" y=\"356\" text-anchor=\"start\">Mesmo banco</text>\n<path class=\"rel\" d=\"M260 566 L875 566 L875 514\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"570\" y=\"558\" text-anchor=\"middle\">Dispara funções agendadas</text>\n<path class=\"rel\" d=\"M50 560 L40 560 L40 334\" marker-end=\"url(#ah)\"/>\n<text class=\"t-rel\" x=\"46\" y=\"352\" text-anchor=\"start\">Chama /api/cron</text>\n<g class=\"n n-ext\">\n<rect x=\"20\" y=\"660\" width=\"960\" height=\"60\" rx=\"8\"/>\n<text class=\"t-name\" x=\"500.0\" y=\"684.0\" text-anchor=\"middle\">Sistemas externos</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"705.0\" text-anchor=\"middle\">Provedores e ERPs · ProFrotas · ANP e Base dos Dados · FIPE · Stripe · Anthropic · Resend · Mapas · Google · Monitoramento</text>\n</g>\n<path class=\"rel\" d=\"M500 638 L500 658\" marker-end=\"url(#ah)\" marker-start=\"url(#ah)\"/><text class=\"t-rel\" x=\"512\" y=\"652\" text-anchor=\"start\">Web app e Edge Functions integram por HTTPS</text></svg></figure>\n    <dl class=\"elements\">\n      <div class=\"el\"><dt>Web app</dt><dd>O coração do produto: painel de todos os perfis, landing, demo interativa, API de integrações, as rotinas chamadas pelo agendador e a área restrita de documentação técnica (<code>/documentacao</code>).</dd></div>\n      <div class=\"el\"><dt>PDV FNI</dt><dd>Aplicação Next.js separada (<code>pdv-fni</code>) para o caixa do posto. Fala só com o Supabase, por RPCs <code>SECURITY DEFINER</code>. Detalhes na seção PDV FNI.</dd></div>\n      <div class=\"el\"><dt>PWAs Flutter</dt><dd>Motorista (<code>estrada-que-cuida</code>) e gestor (<code>estudo-de-rede/flutter</code>). Ambos usam só o SDK do Supabase, com as mesmas regras de acesso da web. O motorista inicia e avalia abastecimentos no PDV; o gestor libera os negados e aprova ou recusa pedidos de ajuste (tela Pedidos de Ajuste, com bolinha no menu). No PWA do gestor, a lista de Veículos se atualiza ao vivo pelo Realtime.</dd></div>\n      <div class=\"el\"><dt>PostgreSQL</dt><dd>Fonte única da verdade. A view <code>abastecimentos_unificado</code> junta ProFrotas, integrações externas e abastecimentos internos.</dd></div>\n      <div class=\"el\"><dt>Edge Functions</dt><dd>Funções em Deno para o que não cabe no app: checkout e webhook do Stripe, e-mails pelo Resend, alertas, atualização de preços e de postos da ANP. A função <code>pdv-ajuste-email</code> é disparada por gatilho em <code>pdv_ajustes</code> (não pelo agendador) a cada pedido de ajuste novo ou decidido.</dd></div>\n      <div class=\"el\"><dt>Agendador</dt><dd><code>pg_cron</code> roda robôs em SQL e usa <code>pg_net</code> para chamar o Web app e as Edge Functions. Detalhes em Rotinas agendadas.</dd></div>\n      <div class=\"el\"><dt>Legado Python</dt><dd>Streamlit (<code>app.</code>) e FastAPI (<code>api.</code>) seguem publicados, mas desde 1 de outubro nenhum app depende deles. Falta só desligar. Ver Achados.</dd></div>\n    </dl>\n  </section>\n\n  <section id=\"componentes\">\n    <div class=\"sec-head\">\n      <span class=\"eyebrow\">Nível 3</span>\n      <h2>Componentes do Web app</h2>\n      <p>O Web app tem quatro portas de entrada, uma para cada tipo de chamador. Atrás delas, o painel e as Server Actions concentram as regras de tela, e as bibliotecas de <code>src/lib</code> concentram as regras de negócio reaproveitadas pelas portas.</p>\n    </div>\n    <figure><svg viewBox=\"0 0 1000 744\" role=\"img\" aria-labelledby=\"t-Nível \"><title>Nível 3: componentes do Web app</title><desc>Middleware, API de integrações, rotinas, webhooks, painel, Server Actions, assistente IA, componentes ao vivo e bibliotecas de domínio.</desc><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M1 1L9 5L1 9\" class=\"ahead\"/></marker></defs><g class=\"n n-person\">\n<rect x=\"30\" y=\"14\" width=\"220\" height=\"56\" rx=\"14\"/>\n<text class=\"t-name\" x=\"140.0\" y=\"38.0\" text-anchor=\"middle\">Navegador</text>\n<text class=\"t-tech\" x=\"140.0\" y=\"55.0\" text-anchor=\"middle\">[gestores, postos, FNI]</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"270\" y=\"14\" width=\"220\" height=\"56\" rx=\"8\"/>\n<text class=\"t-name\" x=\"380.0\" y=\"38.0\" text-anchor=\"middle\">Provedores e ERPs</text>\n<text class=\"t-tech\" x=\"380.0\" y=\"55.0\" text-anchor=\"middle\">[chave de API por empresa]</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"510\" y=\"14\" width=\"220\" height=\"56\" rx=\"8\"/>\n<text class=\"t-name\" x=\"620.0\" y=\"38.0\" text-anchor=\"middle\">Agendador pg_cron</text>\n<text class=\"t-tech\" x=\"620.0\" y=\"55.0\" text-anchor=\"middle\">[Bearer CRON_SECRET]</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"750\" y=\"14\" width=\"220\" height=\"56\" rx=\"8\"/>\n<text class=\"t-name\" x=\"860.0\" y=\"38.0\" text-anchor=\"middle\">Monitoramento e fiscal</text>\n<text class=\"t-tech\" x=\"860.0\" y=\"55.0\" text-anchor=\"middle\">[webhooks]</text>\n</g>\n<g class=\"b\"><rect x=\"10\" y=\"96\" width=\"980\" height=\"540\" rx=\"12\"/>\n<text class=\"t-bound\" x=\"24\" y=\"116\">Web app</text>\n<text class=\"t-boundsub\" x=\"24\" y=\"132\">Next.js 15 · TypeScript · App Router</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"30\" y=\"146\" width=\"220\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"140.0\" y=\"167.0\" text-anchor=\"middle\">Middleware</text>\n<text class=\"t-tech\" x=\"140.0\" y=\"184.0\" text-anchor=\"middle\">[middleware.ts]</text>\n<text class=\"t-desc\" x=\"140.0\" y=\"203.0\" text-anchor=\"middle\">Sessão, MFA, rotas públicas e</text>\n<text class=\"t-desc\" x=\"140.0\" y=\"218.0\" text-anchor=\"middle\">plano suspenso</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"270\" y=\"146\" width=\"220\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"380.0\" y=\"167.0\" text-anchor=\"middle\">API de integrações</text>\n<text class=\"t-tech\" x=\"380.0\" y=\"184.0\" text-anchor=\"middle\">[/api/integracoes · /api/cadastros]</text>\n<text class=\"t-desc\" x=\"380.0\" y=\"203.0\" text-anchor=\"middle\">22 + 5 rotas REST, escopos e</text>\n<text class=\"t-desc\" x=\"380.0\" y=\"218.0\" text-anchor=\"middle\">limite de uso</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"510\" y=\"146\" width=\"220\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"620.0\" y=\"167.0\" text-anchor=\"middle\">Rotinas agendadas</text>\n<text class=\"t-tech\" x=\"620.0\" y=\"184.0\" text-anchor=\"middle\">[/api/cron · 7 rotas]</text>\n<text class=\"t-desc\" x=\"620.0\" y=\"203.0\" text-anchor=\"middle\">Sync ProFrotas, FIPE,</text>\n<text class=\"t-desc\" x=\"620.0\" y=\"218.0\" text-anchor=\"middle\">insights IA, conciliação</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"750\" y=\"146\" width=\"220\" height=\"84\" rx=\"8\"/>\n<text class=\"t-name\" x=\"860.0\" y=\"167.0\" text-anchor=\"middle\">Webhooks e utilitários</text>\n<text class=\"t-tech\" x=\"860.0\" y=\"184.0\" text-anchor=\"middle\">[/api/webhooks · /api/ocr]</text>\n<text class=\"t-desc\" x=\"860.0\" y=\"203.0\" text-anchor=\"middle\">Fiscal, cobrança,</text>\n<text class=\"t-desc\" x=\"860.0\" y=\"218.0\" text-anchor=\"middle\">UptimeRobot, OCR de cupom</text>\n</g>\n<path class=\"rel\" d=\"M140 70 L140 144\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M380 70 L380 144\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M620 70 L620 144\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M860 70 L860 144\" marker-end=\"url(#ah)\"/>\n<g class=\"n n-container\">\n<rect x=\"30\" y=\"270\" width=\"170\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"115.0\" y=\"295.0\" text-anchor=\"middle\">Páginas públicas</text>\n<text class=\"t-tech\" x=\"115.0\" y=\"312.0\" text-anchor=\"middle\">[App Router]</text>\n<text class=\"t-desc\" x=\"115.0\" y=\"331.0\" text-anchor=\"middle\">Landing, demo, índice</text>\n<text class=\"t-desc\" x=\"115.0\" y=\"346.0\" text-anchor=\"middle\">de preços, rastreio</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"215\" y=\"270\" width=\"275\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"352.5\" y=\"295.0\" text-anchor=\"middle\">Painel</text>\n<text class=\"t-tech\" x=\"352.5\" y=\"312.0\" text-anchor=\"middle\">[91 módulos · 197 páginas]</text>\n<text class=\"t-desc\" x=\"352.5\" y=\"331.0\" text-anchor=\"middle\">Server Components que consultam com a</text>\n<text class=\"t-desc\" x=\"352.5\" y=\"346.0\" text-anchor=\"middle\">sessão do usuário</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"510\" y=\"270\" width=\"220\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"620.0\" y=\"295.0\" text-anchor=\"middle\">Server Actions</text>\n<text class=\"t-tech\" x=\"620.0\" y=\"312.0\" text-anchor=\"middle\">[89 arquivos actions.ts]</text>\n<text class=\"t-desc\" x=\"620.0\" y=\"331.0\" text-anchor=\"middle\">Gravações, contagem das</text>\n<text class=\"t-desc\" x=\"620.0\" y=\"346.0\" text-anchor=\"middle\">bolinhas, avisos</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"750\" y=\"270\" width=\"220\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"860.0\" y=\"295.0\" text-anchor=\"middle\">Assistente IA</text>\n<text class=\"t-tech\" x=\"860.0\" y=\"312.0\" text-anchor=\"middle\">[lib/assistenteIA · Claude]</text>\n<text class=\"t-desc\" x=\"860.0\" y=\"331.0\" text-anchor=\"middle\">Responde em português</text>\n<text class=\"t-desc\" x=\"860.0\" y=\"346.0\" text-anchor=\"middle\">consultando os dados sob RLS</text>\n</g>\n<path class=\"rel\" d=\"M100 232 L100 268\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M240 232 L240 268\" marker-end=\"url(#ah)\"/>\n<path class=\"rel\" d=\"M490 316 L508 316\" marker-end=\"url(#ah)\"/>\n<g class=\"n n-container\">\n<rect x=\"30\" y=\"402\" width=\"220\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"140.0\" y=\"427.0\" text-anchor=\"middle\">Componentes ao vivo</text>\n<text class=\"t-tech\" x=\"140.0\" y=\"444.0\" text-anchor=\"middle\">[React no navegador]</text>\n<text class=\"t-desc\" x=\"140.0\" y=\"463.0\" text-anchor=\"middle\">Bolinhas do menu, aviso de</text>\n<text class=\"t-desc\" x=\"140.0\" y=\"478.0\" text-anchor=\"middle\">abastecimento, chat de fretes</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"270\" y=\"402\" width=\"460\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"500.0\" y=\"427.0\" text-anchor=\"middle\">Bibliotecas de domínio</text>\n<text class=\"t-tech\" x=\"500.0\" y=\"444.0\" text-anchor=\"middle\">[src/lib · 99 módulos]</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"463.0\" text-anchor=\"middle\">Sync ProFrotas, preços ANP, FIPE, roteirização, permissões,</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"478.0\" text-anchor=\"middle\">cache, Pix, provedores fiscal e de cobrança (simulados)</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"750\" y=\"402\" width=\"220\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"860.0\" y=\"427.0\" text-anchor=\"middle\">OCR</text>\n<text class=\"t-tech\" x=\"860.0\" y=\"444.0\" text-anchor=\"middle\">[tesseract.js]</text>\n<text class=\"t-desc\" x=\"860.0\" y=\"463.0\" text-anchor=\"middle\">Lê cupons de abastecimento e</text>\n<text class=\"t-desc\" x=\"860.0\" y=\"478.0\" text-anchor=\"middle\">documentos</text>\n</g>\n<path class=\"rel\" d=\"M350 364 L350 400\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"358\" y=\"386\" text-anchor=\"start\">Usa</text>\n<path class=\"rel\" d=\"M620 364 L620 400\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"628\" y=\"386\" text-anchor=\"start\">Usa</text>\n<g class=\"n n-container\">\n<rect x=\"270\" y=\"534\" width=\"460\" height=\"82\" rx=\"8\"/>\n<text class=\"t-name\" x=\"500.0\" y=\"554.0\" text-anchor=\"middle\">Clientes Supabase</text>\n<text class=\"t-tech\" x=\"500.0\" y=\"571.0\" text-anchor=\"middle\">[lib/supabase]</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"590.0\" text-anchor=\"middle\">server: sessão do usuário e RLS · admin: chave de serviço, só no</text>\n<text class=\"t-desc\" x=\"500.0\" y=\"605.0\" text-anchor=\"middle\">servidor · browser: Realtime</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"750\" y=\"534\" width=\"220\" height=\"82\" rx=\"8\"/>\n<text class=\"t-name\" x=\"860.0\" y=\"554.0\" text-anchor=\"middle\">Observabilidade</text>\n<text class=\"t-tech\" x=\"860.0\" y=\"571.0\" text-anchor=\"middle\">[logger · request-id · Sentry]</text>\n<text class=\"t-desc\" x=\"860.0\" y=\"590.0\" text-anchor=\"middle\">Log de cada consulta com</text>\n<text class=\"t-desc\" x=\"860.0\" y=\"605.0\" text-anchor=\"middle\">duração</text>\n</g>\n<path class=\"rel\" d=\"M500 496 L500 532\" marker-end=\"url(#ah)\"/>\n<g class=\"n n-db\">\n<rect x=\"30\" y=\"674\" width=\"580\" height=\"54\" rx=\"8\"/>\n<text class=\"t-name\" x=\"320.0\" y=\"697.0\" text-anchor=\"middle\">Supabase</text>\n<text class=\"t-tech\" x=\"320.0\" y=\"714.0\" text-anchor=\"middle\">[PostgreSQL · Auth · Realtime · Storage]</text>\n</g>\n<g class=\"n n-ext\">\n<rect x=\"630\" y=\"674\" width=\"340\" height=\"54\" rx=\"8\"/>\n<text class=\"t-name\" x=\"800.0\" y=\"697.0\" text-anchor=\"middle\">Sistemas externos</text>\n<text class=\"t-tech\" x=\"800.0\" y=\"714.0\" text-anchor=\"middle\">[ProFrotas · ANP · FIPE · Claude · Sentry]</text>\n</g>\n<path class=\"rel\" d=\"M500 618 L500 672\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"508\" y=\"650\" text-anchor=\"start\">Consultas e eventos</text>\n<path class=\"rel\" d=\"M140 496 L140 672\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"148\" y=\"600\" text-anchor=\"start\">Assina eventos</text><text class=\"t-rel\" x=\"148\" y=\"614\" text-anchor=\"start\">do Realtime</text>\n<path class=\"rel\" d=\"M730 450 L740 450 L740 672\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"746\" y=\"650\" text-anchor=\"start\">HTTPS</text></svg></figure>\n    <dl class=\"elements\">\n      <div class=\"el\"><dt>Middleware</dt><dd>Renova a sessão, libera só as rotas públicas listadas, exige MFA e redireciona contas com assinatura suspensa.</dd></div>\n      <div class=\"el\"><dt>API de integrações</dt><dd><code>lib/apiAuth</code> valida a chave por hash, confere o escopo e devolve um cliente com acesso restrito à empresa da chave. <code>lib/rateLimit</code> limita o volume.</dd></div>\n      <div class=\"el\"><dt>Server Actions</dt><dd>Toda gravação feita pelas telas. Também a fonte única das 13 contagens das bolinhas do menu (<code>contarBadgesMenuAcao</code>).</dd></div>\n      <div class=\"el\"><dt>Clientes Supabase</dt><dd>Três clientes com papéis separados. O cliente com chave de serviço existe só no servidor e só nas rotas que precisam ignorar o RLS.</dd></div>\n      <div class=\"el\"><dt>Assistente IA</dt><dd>Usa o modelo <code>claude-sonnet-5</code> com ferramentas de consulta que rodam com a sessão do usuário, então o RLS vale também para a IA.</dd></div>\n      <div class=\"el\"><dt>Documentação técnica protegida</dt><dd>Rotas <code>/documentacao</code> (índice), <code>/documentacao/arquitetura</code> e <code>/documentacao/funcional</code>, linkadas no rodapé da landing. Três barreiras em <code>acessoDocumentacao.ts</code>: sessão (senão vai para <code>/login</code>), MFA com fator TOTP verificado e sessão em aal2 (senão <code>/mfa-setup</code>) e perfil admin (senão 403). Os HTMLs vão embutidos no build como módulos TypeScript, gerados por <code>scripts/sincronizar-documentacao.mjs</code> a partir da pasta Benchmark, e o Mermaid é servido de <code>/vendor/mermaid.min.js</code> porque a CSP não libera CDN. As respostas saem com <code>Cache-Control: private, no-store</code> e <code>noindex</code>.</dd></div>\n      <div class=\"el\"><dt>Observabilidade</dt><dd>Cada consulta ao banco vira log com duração e <code>requestId</code>. Foi o que permitiu medir a latência descrita em Achados.</dd></div>\n    </dl>\n  </section>\n\n  <section id=\"codigo\">\n    <div class=\"sec-head\">\n      <span class=\"eyebrow\">Nível 4</span>\n      <h2>Código: aviso de novo abastecimento</h2>\n      <p>O nível de código não se desenha para o sistema inteiro. Aqui está um recorte real, implementado em setembro: o caminho entre o motorista registrar um abastecimento e o gestor ver o aviso e a lista atualizada, com os nomes que estão no código.</p>\n    </div>\n    <figure><svg viewBox=\"0 0 1000 576\" role=\"img\" aria-labelledby=\"t-Nível \"><title>Nível 4: fluxo do aviso de novo abastecimento</title><desc>Sequência do INSERT feito pelo PWA até o cartão de aviso e a atualização da tela de abastecimentos.</desc><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M1 1L9 5L1 9\" class=\"ahead\"/></marker></defs><g class=\"n n-container\">\n<rect x=\"9.5\" y=\"16\" width=\"145\" height=\"40\" rx=\"8\"/>\n<text class=\"t-name\" x=\"82.0\" y=\"39.5\" text-anchor=\"middle\">PWA do motorista</text>\n</g>\n<line class=\"life\" x1=\"82\" y1=\"58\" x2=\"82\" y2=\"560\"/>\n<g class=\"n n-container\">\n<rect x=\"164.5\" y=\"16\" width=\"145\" height=\"40\" rx=\"8\"/>\n<text class=\"t-name\" x=\"237.0\" y=\"39.5\" text-anchor=\"middle\">PostgreSQL</text>\n</g>\n<line class=\"life\" x1=\"237\" y1=\"58\" x2=\"237\" y2=\"560\"/>\n<g class=\"n n-container\">\n<rect x=\"319.5\" y=\"16\" width=\"145\" height=\"40\" rx=\"8\"/>\n<text class=\"t-name\" x=\"392.0\" y=\"39.5\" text-anchor=\"middle\">Realtime</text>\n</g>\n<line class=\"life\" x1=\"392\" y1=\"58\" x2=\"392\" y2=\"560\"/>\n<g class=\"n n-container\">\n<rect x=\"474.5\" y=\"16\" width=\"145\" height=\"40\" rx=\"8\"/>\n<text class=\"t-name\" x=\"547.0\" y=\"39.5\" text-anchor=\"middle\">ProvedorBadgesMenu</text>\n</g>\n<line class=\"life\" x1=\"547\" y1=\"58\" x2=\"547\" y2=\"560\"/>\n<g class=\"n n-container\">\n<rect x=\"629.5\" y=\"16\" width=\"145\" height=\"40\" rx=\"8\"/>\n<text class=\"t-name\" x=\"702.0\" y=\"39.5\" text-anchor=\"middle\">Server Actions</text>\n</g>\n<line class=\"life\" x1=\"702\" y1=\"58\" x2=\"702\" y2=\"560\"/>\n<g class=\"n n-container\">\n<rect x=\"785.0\" y=\"16\" width=\"200\" height=\"40\" rx=\"8\"/>\n<text class=\"t-name\" x=\"885.0\" y=\"39.5\" text-anchor=\"middle\">AvisoNovoAbastecimento</text>\n</g>\n<line class=\"life\" x1=\"885\" y1=\"58\" x2=\"885\" y2=\"560\"/>\n<path class=\"rel\" d=\"M82 100 L235 100\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"160\" y=\"92\" text-anchor=\"middle\">1. INSERT em abastecimentos_internos</text>\n<path class=\"rel\" d=\"M237 152 L390 152\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"314\" y=\"144\" text-anchor=\"middle\">2. Evento da publicação supabase_realtime</text>\n<path class=\"rel\" d=\"M392 204 L545 204\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"470\" y=\"196\" text-anchor=\"middle\">3. postgres_changes, filtrado pelo RLS</text>\n<path class=\"rel\" d=\"M547 256 L700 256\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"624\" y=\"248\" text-anchor=\"middle\">4. contarBadgesMenuAcao() após 1,5 s</text>\n<path class=\"rel\" d=\"M547 308 L883 308\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"716\" y=\"300\" text-anchor=\"middle\">5. Avisa os assinantes do ciclo</text>\n<path class=\"rel\" d=\"M885 360 L704 360\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"794\" y=\"352\" text-anchor=\"middle\">6. novosAbastecimentosAcao(): janela de 15 min</text>\n<path class=\"rel\" d=\"M702 412 L239 412\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"470\" y=\"404\" text-anchor=\"middle\">7. SELECT na view abastecimentos_unificado</text>\n<path class=\"rel\" d=\"M885 456 h28 v18 h-26\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"875\" y=\"462\" text-anchor=\"end\">8. Mostra o cartão via createPortal no &lt;body&gt;</text>\n<path class=\"rel\" d=\"M885 508 h28 v18 h-26\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"875\" y=\"514\" text-anchor=\"end\">9. router.refresh() e confere o marcador em 10 s</text></svg><figcaption>Arquivos: <code>_components/ProvedorBadgesMenu.tsx</code>, <code>badgesMenuActions.ts</code>, <code>AvisoNovoAbastecimento.tsx</code>, <code>novosAbastecimentosActions.ts</code> e <code>abastecimentos/page.tsx</code>. A consulta a cada 60 s continua como reserva caso o tempo real caia.</figcaption></figure>\n  </section>\n\n  <section id=\"pdv\">\n    <div class=\"sec-head\">\n      <span class=\"eyebrow\">Complemento · 3 de outubro de 2026</span>\n      <h2>PDV FNI</h2>\n      <p>O ponto de venda do posto é uma aplicação separada, ligada ao mesmo banco. O motorista gera um código no celular, o frentista ou caixa valida no PDV, e o abastecimento entra na mesma base de pontos, regras e relatórios do restante do FNI. Abaixo, os componentes e o fluxo completo, do código à avaliação.</p>\n    </div>\n    <figure><svg viewBox=\"0 0 1000 730\" role=\"img\" aria-labelledby=\"t-Nível \"><title>PDV FNI: componentes</title><desc>Telas do PDV Next.js, o Supabase com RPCs e os apps que participam do abastecimento.</desc><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M1 1L9 5L1 9\" class=\"ahead\"/></marker></defs><g class=\"n n-person\">\n<rect x=\"20\" y=\"16\" width=\"225\" height=\"58\" rx=\"14\"/>\n<text class=\"t-name\" x=\"132.5\" y=\"42.5\" text-anchor=\"middle\">Frentistas e caixas</text>\n<text class=\"t-tech\" x=\"132.5\" y=\"59.5\" text-anchor=\"middle\">[Pessoa · navegador]</text>\n</g>\n<path class=\"rel\" d=\"M132 74 L132 98\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"142\" y=\"92\" text-anchor=\"start\">HTTPS</text>\n<g class=\"b\"><rect x=\"10\" y=\"100\" width=\"980\" height=\"336\" rx=\"12\"/>\n<text class=\"t-bound\" x=\"24\" y=\"120\">PDV FNI</text>\n<text class=\"t-boundsub\" x=\"24\" y=\"136\">Next.js 15 · TypeScript · Tailwind · Railway us-east4 · pdv.fxgestaodefrotasonline.com</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"30\" y=\"152\" width=\"225\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"142.5\" y=\"180.5\" text-anchor=\"middle\">Login e sessão</text>\n<text class=\"t-tech\" x=\"142.5\" y=\"197.5\" text-anchor=\"middle\">[/login · @supabase/ssr]</text>\n<text class=\"t-desc\" x=\"142.5\" y=\"212.5\" text-anchor=\"middle\">E-mail e senha pelo Supabase</text>\n<text class=\"t-desc\" x=\"142.5\" y=\"227.5\" text-anchor=\"middle\">Auth; cookie e ação sair()</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"270\" y=\"152\" width=\"225\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"382.5\" y=\"173.0\" text-anchor=\"middle\">Layout e menu lateral</text>\n<text class=\"t-tech\" x=\"382.5\" y=\"190.0\" text-anchor=\"middle\">[(pdv)/layout.tsx · MenuLateral]</text>\n<text class=\"t-desc\" x=\"382.5\" y=\"205.0\" text-anchor=\"middle\">Contexto da revenda; menu com</text>\n<text class=\"t-desc\" x=\"382.5\" y=\"220.0\" text-anchor=\"middle\">logo, busca e tema claro,</text>\n<text class=\"t-desc\" x=\"382.5\" y=\"235.0\" text-anchor=\"middle\">escuro ou automático</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"510\" y=\"152\" width=\"225\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"622.5\" y=\"180.5\" text-anchor=\"middle\">Pista</text>\n<text class=\"t-tech\" x=\"622.5\" y=\"197.5\" text-anchor=\"middle\">[/ · página inicial]</text>\n<text class=\"t-desc\" x=\"622.5\" y=\"212.5\" text-anchor=\"middle\">Bombas e bicos em visual de</text>\n<text class=\"t-desc\" x=\"622.5\" y=\"227.5\" text-anchor=\"middle\">pista; escolhe o bico livre</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"750\" y=\"152\" width=\"225\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"862.5\" y=\"173.0\" text-anchor=\"middle\">Validar e Pré-Pedido</text>\n<text class=\"t-tech\" x=\"862.5\" y=\"190.0\" text-anchor=\"middle\">[/validar · /pre-pedido]</text>\n<text class=\"t-desc\" x=\"862.5\" y=\"205.0\" text-anchor=\"middle\">Código e OTP do motorista;</text>\n<text class=\"t-desc\" x=\"862.5\" y=\"220.0\" text-anchor=\"middle\">OTP do Pré-Pedido, limite</text>\n<text class=\"t-desc\" x=\"862.5\" y=\"235.0\" text-anchor=\"middle\">e conclusão</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"30\" y=\"260\" width=\"225\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"142.5\" y=\"288.5\" text-anchor=\"middle\">Abastecimento</text>\n<text class=\"t-tech\" x=\"142.5\" y=\"305.5\" text-anchor=\"middle\">[/abastecimento/[id]]</text>\n<text class=\"t-desc\" x=\"142.5\" y=\"320.5\" text-anchor=\"middle\">Itens, OTP do Pré-Pedido,</text>\n<text class=\"t-desc\" x=\"142.5\" y=\"335.5\" text-anchor=\"middle\">comprovante e situação</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"270\" y=\"260\" width=\"225\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"382.5\" y=\"288.5\" text-anchor=\"middle\">Extrato</text>\n<text class=\"t-tech\" x=\"382.5\" y=\"305.5\" text-anchor=\"middle\">[/extrato]</text>\n<text class=\"t-desc\" x=\"382.5\" y=\"320.5\" text-anchor=\"middle\">Lista com filtros, orientação</text>\n<text class=\"t-desc\" x=\"382.5\" y=\"335.5\" text-anchor=\"middle\">de NF-e e comprovante</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"510\" y=\"260\" width=\"225\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"622.5\" y=\"281.0\" text-anchor=\"middle\">Dashboard</text>\n<text class=\"t-tech\" x=\"622.5\" y=\"298.0\" text-anchor=\"middle\">[/dashboard]</text>\n<text class=\"t-desc\" x=\"622.5\" y=\"313.0\" text-anchor=\"middle\">Volume, valor, modalidades e</text>\n<text class=\"t-desc\" x=\"622.5\" y=\"328.0\" text-anchor=\"middle\">resgates, com filtros por</text>\n<text class=\"t-desc\" x=\"622.5\" y=\"343.0\" text-anchor=\"middle\">cliente, placa e motorista</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"750\" y=\"260\" width=\"225\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"862.5\" y=\"288.5\" text-anchor=\"middle\">Cadastros</text>\n<text class=\"t-tech\" x=\"862.5\" y=\"305.5\" text-anchor=\"middle\">[/bicos · /produtos · /terminais]</text>\n<text class=\"t-desc\" x=\"862.5\" y=\"320.5\" text-anchor=\"middle\">Bombas, bicos, produtos (inteiros</text>\n<text class=\"t-desc\" x=\"862.5\" y=\"335.5\" text-anchor=\"middle\">ou em litros) e terminais</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"30\" y=\"368\" width=\"225\" height=\"52\" rx=\"8\"/>\n<text class=\"t-name\" x=\"142.5\" y=\"385.0\" text-anchor=\"middle\">Resgates · /resgates</text>\n<text class=\"t-desc\" x=\"142.5\" y=\"404.0\" text-anchor=\"middle\">Valida e baixa o voucher;</text>\n<text class=\"t-desc\" x=\"142.5\" y=\"419.0\" text-anchor=\"middle\">grava terminal e valor</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"270\" y=\"368\" width=\"225\" height=\"52\" rx=\"8\"/>\n<text class=\"t-name\" x=\"382.5\" y=\"385.0\" text-anchor=\"middle\">OrientacaoNF</text>\n<text class=\"t-desc\" x=\"382.5\" y=\"404.0\" text-anchor=\"middle\">Parâmetros de NF do cliente</text>\n<text class=\"t-desc\" x=\"382.5\" y=\"419.0\" text-anchor=\"middle\">no extrato e no comprovante</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"510\" y=\"368\" width=\"225\" height=\"52\" rx=\"8\"/>\n<text class=\"t-name\" x=\"622.5\" y=\"385.0\" text-anchor=\"middle\">EmEsperaDock</text>\n<text class=\"t-desc\" x=\"622.5\" y=\"404.0\" text-anchor=\"middle\">Fila de abastecimentos</text>\n<text class=\"t-desc\" x=\"622.5\" y=\"419.0\" text-anchor=\"middle\">aguardando o gestor</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"750\" y=\"368\" width=\"225\" height=\"52\" rx=\"8\"/>\n<text class=\"t-name\" x=\"862.5\" y=\"385.0\" text-anchor=\"middle\">Biblioteca visual</text>\n<text class=\"t-desc\" x=\"862.5\" y=\"404.0\" text-anchor=\"middle\">BombaIcone, Icones, Etapas,</text>\n<text class=\"t-desc\" x=\"862.5\" y=\"419.0\" text-anchor=\"middle\">combustiveis, produtosPdv</text>\n</g>\n<g class=\"b\"><rect x=\"10\" y=\"476\" width=\"980\" height=\"156\" rx=\"12\"/>\n<text class=\"t-bound\" x=\"24\" y=\"496\">Supabase</text>\n<text class=\"t-boundsub\" x=\"24\" y=\"512\">Região São Paulo (sa-east-1)</text>\n</g>\n<g class=\"n n-db\">\n<rect x=\"30\" y=\"524\" width=\"600\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"330.0\" y=\"552.5\" text-anchor=\"middle\">PostgreSQL</text>\n<text class=\"t-tech\" x=\"330.0\" y=\"569.5\" text-anchor=\"middle\">[RPCs SECURITY DEFINER + RLS]</text>\n<text class=\"t-desc\" x=\"330.0\" y=\"584.5\" text-anchor=\"middle\">9 tabelas e 47 funções do PDV: iniciar, validar, concluir,</text>\n<text class=\"t-desc\" x=\"330.0\" y=\"599.5\" text-anchor=\"middle\">regras, negar, liberar, voucher, NF-e, espera e OTP do Pré-Pedido</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"650\" y=\"524\" width=\"180\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"740.0\" y=\"552.5\" text-anchor=\"middle\">Auth</text>\n<text class=\"t-tech\" x=\"740.0\" y=\"569.5\" text-anchor=\"middle\">[Supabase Auth]</text>\n<text class=\"t-desc\" x=\"740.0\" y=\"584.5\" text-anchor=\"middle\">Mesmo login do FNI;</text>\n<text class=\"t-desc\" x=\"740.0\" y=\"599.5\" text-anchor=\"middle\">perfil posto</text>\n</g>\n<g class=\"n n-db\">\n<rect x=\"850\" y=\"524\" width=\"120\" height=\"92\" rx=\"8\"/>\n<text class=\"t-name\" x=\"910.0\" y=\"552.5\" text-anchor=\"middle\">Robôs</text>\n<text class=\"t-tech\" x=\"910.0\" y=\"569.5\" text-anchor=\"middle\">[pg_cron]</text>\n<text class=\"t-desc\" x=\"910.0\" y=\"584.5\" text-anchor=\"middle\">Leituras de</text>\n<text class=\"t-desc\" x=\"910.0\" y=\"599.5\" text-anchor=\"middle\">bombas de teste</text>\n</g>\n<path class=\"rel\" d=\"M330 436 L330 522\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"340\" y=\"464\" text-anchor=\"start\">RPCs e consultas com RLS</text>\n<path class=\"rel\" d=\"M740 436 L740 522\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"750\" y=\"464\" text-anchor=\"start\">Login e sessão</text>\n<g class=\"n n-container\">\n<rect x=\"30\" y=\"656\" width=\"300\" height=\"58\" rx=\"8\"/>\n<text class=\"t-name\" x=\"180.0\" y=\"682.5\" text-anchor=\"middle\">PWA do motorista</text>\n<text class=\"t-tech\" x=\"180.0\" y=\"699.5\" text-anchor=\"middle\">[Flutter Web · Railway]</text>\n</g>\n<g class=\"n n-container\">\n<rect x=\"350\" y=\"656\" width=\"300\" height=\"58\" rx=\"8\"/>\n<text class=\"t-name\" x=\"500.0\" y=\"682.5\" text-anchor=\"middle\">Web app e PWA do gestor</text>\n<text class=\"t-tech\" x=\"500.0\" y=\"699.5\" text-anchor=\"middle\">[Next.js · Flutter Web]</text>\n</g>\n<path class=\"rel\" d=\"M180 656 L180 634\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"190\" y=\"649\" text-anchor=\"start\">Gera código, acompanha e avalia</text>\n<path class=\"rel\" d=\"M500 656 L500 634\" marker-end=\"url(#ah)\"/><text class=\"t-rel\" x=\"510\" y=\"649\" text-anchor=\"start\">Libera abastecimentos negados</text></svg><figcaption>Repositório <code>pdv-fni</code>, serviço no Railway com domínio próprio. O PDV não tem API própria: toda regra de negócio mora em funções do PostgreSQL.</figcaption></figure>\n    <figure><svg viewBox=\"0 0 1000 700\" role=\"img\" aria-labelledby=\"t-Nível \"><title>PDV FNI: fluxo do abastecimento</title><desc>Sequência do código do motorista até a avaliação do posto, com liberação de abastecimento negado.</desc><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M1 1L9 5L1 9\" class=\"ahead\"/></marker></defs><g class=\"n n-container\">\n<rect x=\"15\" y=\"16\" width=\"170\" height=\"40\" rx=\"8\"/>\n<text class=\"t-name\" x=\"100.0\" y=\"42.0\" text-anchor=\"middle\">PWA do motorista</text>\n</g>\n<line class=\"life\" x1=\"100\" y1=\"58\" x2=\"100\" y2=\"690\"/>\n<g class=\"n n-container\">\n<rect x=\"255\" y=\"16\" width=\"170\" height=\"40\" rx=\"8\"/>\n<text class=\"t-name\" x=\"340.0\" y=\"42.0\" text-anchor=\"middle\">PDV FNI</text>\n</g>\n<line class=\"life\" x1=\"340\" y1=\"58\" x2=\"340\" y2=\"690\"/>\n<g class=\"n n-container\">\n<rect x=\"535\" y=\"16\" width=\"170\" height=\"40\" rx=\"8\"/>\n<text class=\"t-name\" x=\"620.0\" y=\"42.0\" text-anchor=\"middle\">PostgreSQL (RPCs)</text>\n</g>\n<line class=\"life\" x1=\"620\" y1=\"58\" x2=\"620\" y2=\"690\"/>\n<g class=\"n n-container\">\n<rect x=\"795\" y=\"16\" width=\"170\" height=\"40\" rx=\"8\"/>\n<text class=\"t-name\" x=\"880.0\" y=\"42.0\" text-anchor=\"middle\">Web app / PWA gestor</text>\n</g>\n<line class=\"life\" x1=\"880\" y1=\"58\" x2=\"880\" y2=\"690\"/>\n<path class=\"rel\" d=\"M100 100 L618 100\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"360\" y=\"92\" text-anchor=\"middle\">1. iniciar_abastecimento_pdv(): gera código + OTP</text>\n<path class=\"rel\" d=\"M340 152 L618 152\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"480\" y=\"144\" text-anchor=\"middle\">2. listar_leituras_bomba_disponiveis_pdv()</text>\n<path class=\"rel\" d=\"M340 204 L618 204\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"480\" y=\"196\" text-anchor=\"middle\">3. validar_codigo_leitura_pdv(código, OTP)</text>\n<path class=\"rel\" d=\"M340 256 L618 256\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"480\" y=\"248\" text-anchor=\"middle\">4. concluir_abastecimento_pdv()</text>\n<path class=\"rel\" d=\"M620 308 h28 v18 h-26\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"610\" y=\"314\" text-anchor=\"end\">5. avaliar_regras_abastecimento_pdv()</text>\n<path class=\"rel\" d=\"M620 372 L342 372\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"480\" y=\"364\" text-anchor=\"middle\">6. se as regras negam: aguarda liberação</text>\n<path class=\"rel\" d=\"M620 424 L878 424\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"750\" y=\"416\" text-anchor=\"middle\">7. Realtime e contagem de negados</text>\n<path class=\"rel\" d=\"M880 476 L622 476\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"750\" y=\"468\" text-anchor=\"middle\">8. decidir_abastecimento_negado_pdv()</text>\n<path class=\"rel\" d=\"M620 528 h28 v18 h-26\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"610\" y=\"522\" text-anchor=\"end\">9. Gatilho credita os pontos:</text>\n<text class=\"t-step\" x=\"610\" y=\"536\" text-anchor=\"end\">creditar_pontos_abastecimento_pdv</text>\n<path class=\"rel\" d=\"M100 596 L618 596\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"360\" y=\"588\" text-anchor=\"middle\">10. status_abastecimento_pdv() a cada 3 s</text>\n<path class=\"rel\" d=\"M100 648 L618 648\" marker-end=\"url(#ah)\"/>\n<text class=\"t-step\" x=\"360\" y=\"640\" text-anchor=\"middle\">11. avaliar_abastecimento_pdv(estrelas, observação)</text>\n</svg><figcaption>Se as regras do cliente aprovam, os passos 6 a 8 não acontecem e o abastecimento já nasce confirmado. O PWA do motorista não lê <code>abastecimentos_pdv</code> direto (RLS): usa o status por RPC. Avaliação são três notas de 1 a 5 (posto, abastecimento, frentista ou caixa) mais observação opcional.</figcaption></figure>\n    <div class=\"table-wrap\"><table><thead><tr><th>Objeto</th><th>Tipo</th><th>Papel</th></tr></thead><tbody>\n<tr class=\"grp\"><td colspan=\"3\">Tabelas</td></tr>\n<tr><td><code>abastecimentos_pdv</code></td><td>tabela</td><td>Transação: situação, código, OTP, valores, decisão de negados</td></tr>\n<tr><td><code>abastecimentos_pdv_itens</code></td><td>tabela</td><td>Itens extras de cada transação (lavagem, loja, etc.)</td></tr>\n<tr><td><code>avaliacoes_abastecimento_pdv</code></td><td>tabela</td><td>Notas do motorista para posto, abastecimento e frentista ou caixa</td></tr>\n<tr><td><code>pdv_bicos_catalogo · pdv_leituras_bomba_disponiveis</code></td><td>tabelas</td><td>Bicos cadastrados e leituras de bomba aguardando uso</td></tr>\n<tr><td><code>fidelidade_resgates · fidelidade_catalogo_itens</code></td><td>tabelas</td><td>Vouchers e benefícios do programa de pontos; ganharam queima (<code>queimado_em</code>, terminal, origem) e <code>valor_a_receber</code>/<code>valor_reembolso</code></td></tr>\n<tr><td><code>parametros_nota_fiscal</code> · <code>parametros_nota_fiscal_destino_uf</code></td><td>tabelas</td><td>Preferências de NF definidas pelo cliente; o PDV lê só pela RPC</td></tr>\n<tr><td><code>produtos_servicos_pdv</code> (<code>unidade</code>, <code>somente_diesel</code>)</td><td>colunas</td><td>Item vendido em unidades inteiras ou em litros com volume fracionado (Arla 32); <code>somente_diesel</code> limita ao diesel</td></tr>\n<tr><td><code>abastecimentos_pdv</code> (<code>espera_dispensada_em</code>, <code>pre_pedido_numero</code>)</td><td>colunas</td><td>Marca o aviso da fila de espera como visto; guarda o código interno da parada do Pré-Pedido usado</td></tr>\n<tr><td><code>pre_pedidos · pre_pedidos_paradas</code> (<code>codigo</code>, <code>otp_seed</code>, <code>valor_previsto</code>, <code>autorizado_pdv_em</code>)</td><td>tabelas</td><td>Pré-Pedido manual ou vindo do Plano de Viagem; cada parada tem posto, limite em litros ou R$ e um código interno aleatório de 6 dígitos (único entre as pendentes) e uma semente (<code>otp_seed</code>) que gera o OTP rotativo. <code>autorizado_pdv_em</code> marca quando o caixa digitou o OTP (vale 60 min)</td></tr>\n<tr><td><code>pdv_ajustes</code> (<code>alteracoes</code>, <code>valores_originais</code>, <code>valores_aplicados</code>)</td><td>tabela</td><td>Pedido de ajuste de abastecimento PDV: quem pediu (posto ou cliente), o que muda, os valores antes e depois, motivo e decisão da contraparte. Um pedido pendente por abastecimento. <code>abastecimentos_pdv.corrigido_por_ajuste_id</code> aponta o pedido que corrigiu a linha</td></tr>\n<tr><td><code>usuarios_app · motoristas</code> (<code>tema_preferido</code>)</td><td>colunas</td><td>Tema escolhido (claro, escuro ou automático), compartilhado entre painel web e os dois PWAs</td></tr>\n<tr><td><code>pdv_terminais · produtos_servicos_pdv · pdv_formas_pagamento_permitidas</code></td><td>tabelas</td><td>Caixas, catálogo de produtos e formas de pagamento aceitas por cliente</td></tr>\n<tr class=\"grp\"><td colspan=\"3\">Funções principais</td></tr>\n<tr><td><code>listar_abastecimentos_em_espera_pdv · dispensar_espera_pdv</code></td><td>RPC</td><td>Fila de espera do caixa: pedidos aguardando, liberados, recusados ou expirados; dispensa o aviso</td></tr>\n<tr><td><code>concluir_abastecimento_pdv</code></td><td>RPC</td><td>Também recusa quantidade zero ou com mais de 3 casas e item &quot;só diesel&quot; fora de abastecimento de diesel; ao queimar a parada de um Pré-Pedido, gera o código da próxima; se volume ou valor passa do limite do Pré-Pedido, recusa de vez (<code>motivo_negacao</code> = <code>pre_pedido_limite</code>), sem fila do gestor</td></tr>\n<tr><td><code>buscar_voucher_pdv · queimar_voucher_fidelidade</code></td><td>RPC</td><td>Caixa confere e baixa o voucher de resgate; grava terminal, origem e valor a receber. O web do posto usa a mesma RPC</td></tr>\n<tr><td><code>listar_resgates_pdv</code></td><td>RPC</td><td>Resgates do período para a tela de resgates e o dashboard</td></tr>\n<tr><td><code>parametros_nf_abastecimento_pdv</code></td><td>RPC</td><td>Resolve os parâmetros de NF do cliente (CNPJ de destino, forma de emissão, dados adicionais) para um abastecimento</td></tr>\n<tr><td><code>_voucher_validar</code></td><td>interna</td><td>Validação única de voucher: empresa, benefício, situação e validade; aceita postos do mesmo grupo econômico do dono do benefício</td></tr>\n<tr><td><code>criar_pre_pedido · cancelar_pre_pedido</code></td><td>RPC</td><td>Gestor cria o Pré-Pedido (placa, motorista opcional, paradas com limite) no painel web e o cancela</td></tr>\n<tr><td><code>consultar_pre_pedido_pdv</code></td><td>RPC</td><td>Tela <code>/pre-pedido</code>: o caixa digita só o OTP de 6 dígitos que o motorista mostra no app; valida para o posto (aceita a janela atual ou a anterior), devolve cliente, placa, motorista e limite e registra a autorização por 60 min. Não vincula abastecimento sozinho</td></tr>\n<tr><td><code>informar_pre_pedido_pdv</code></td><td>RPC</td><td>Alternativa na tela do abastecimento: digita o OTP, confere cliente, placa, posto e se a parada está pendente, e mostra o limite</td></tr>\n<tr><td><code>meus_pre_pedidos_motorista</code></td><td>RPC</td><td>PWA do motorista lê o OTP da parada atual (muda a cada 30 s), os segundos restantes e a rota; vazio quando o cliente não exige Pré-Pedido</td></tr>\n<tr><td><code>_gerar_codigo_pre_pedido</code> · gatilho em <code>pre_pedidos_paradas</code></td><td>interna · gatilho</td><td>Sorteia o código interno livre e a semente do OTP; a 1ª parada nasce com ambos e, ao ser atendida, a próxima recebe novos</td></tr>\n<tr><td><code>iniciar_abastecimento_pre_pedido_pdv</code></td><td>RPC</td><td>Depois do OTP aceito, o caixa escolhe a leitura da bomba na pista e o abastecimento nasce já vinculado ao Pré-Pedido, sem pedir código de abastecimento nem OTP de novo; exige autorização recente do mesmo posto</td></tr>\n<tr><td><code>limite_pre_pedido_abastecimento_pdv</code></td><td>RPC</td><td>Devolve o limite (litros ou R$) do Pré-Pedido vinculado, para mostrar na tela do abastecimento</td></tr>\n<tr><td><code>_pre_pedido_parada_por_otp</code> · <code>consultar_pre_pedido_para_posto</code></td><td>interna · RPC</td><td>Acha a parada pendente do posto cujo OTP bate com o informado; a tela web <code>/pre-pedidos</code> do posto usa a mesma regra</td></tr>\n<tr><td><code>solicitar_ajuste_pdv</code></td><td>RPC</td><td>Posto ou cliente pede a correção de qualquer campo de um abastecimento confirmado, com motivo obrigatório; recusa campo fora da lista e segundo pedido pendente</td></tr>\n<tr><td><code>decidir_ajuste_pdv</code></td><td>RPC</td><td>Só a contraparte aprova ou recusa. Aprovado: corrige o abastecimento, recalcula valores e lança no extrato de pontos a diferença, se já creditados; guarda valores originais e aplicados</td></tr>\n<tr><td><code>cancelar_ajuste_pdv</code> · <code>meus_ajustes_pdv</code></td><td>RPC</td><td>Quem pediu cancela enquanto pendente; a lista traz o que cada lado pode decidir ou cancelar</td></tr>\n<tr><td><code>detectar_acoes_pre_pedido_excedido</code> · <code>executar_acao_pre_pedido_excedido</code></td><td>RPC</td><td>Robô diário: abastecimento de integração, planilha ou lançamento manual de cliente com Pré-Pedido habilitado, sem Pré-Pedido para a placa e o posto ou acima do limite, vira Ação Sugerida. Só avisa; aprovar é dar ciência</td></tr>\n<tr><td><code>definir_tema_preferido · obter_tema_preferido</code></td><td>RPC</td><td>Gravam e leem o tema da conta (usuário do painel ou motorista)</td></tr>\n<tr><td><code>iniciar_abastecimento_pdv</code></td><td>RPC</td><td>Motorista abre a transação e recebe código e OTP</td></tr>\n<tr><td><code>validar_codigo_leitura_pdv · selecionar_leitura_bomba_pdv</code></td><td>RPC</td><td>Posto confere o código e vincula a leitura de bomba</td></tr>\n<tr><td><code>concluir_abastecimento_pdv</code></td><td>RPC</td><td>Fecha a transação e chama a avaliação de regras</td></tr>\n<tr><td><code>avaliar_regras_abastecimento_pdv</code></td><td>RPC</td><td>Aplica as regras de uso do cliente; pode negar. Com Pré-Pedido habilitado, exige o OTP (digitado ou autorizado no caixa) válido para a placa e o posto, dentro do limite de litros ou valor</td></tr>\n<tr><td><code>decidir_abastecimento_negado_pdv · listar_abastecimentos_negados_pdv · contar_abastecimentos_negados_pendentes_pdv</code></td><td>RPC</td><td>Gestor do cliente libera ou mantém a negativa</td></tr>\n<tr><td><code>creditar_pontos_abastecimento_pdv</code></td><td>gatilho</td><td>Credita pontos quando a transação é confirmada</td></tr>\n<tr><td><code>status_abastecimento_pdv · avaliar_abastecimento_pdv</code></td><td>RPC</td><td>Acompanhamento e avaliação no PWA do motorista</td></tr>\n<tr><td><code>contar_ajustes_pdv_pendentes_para_mim</code></td><td>RPC</td><td>Quantos pedidos de ajuste aguardam a decisão do usuário; alimenta bolinha, aviso e banner</td></tr>\n<tr><td><code>registrar_ajuste_no_abastecimento_pdv · notificar_ajuste_pdv_email</code></td><td>gatilho</td><td>Copiam o status e o motivo do último pedido para <code>abastecimentos_pdv</code> e chamam a função de e-mail</td></tr>\n<tr><td><code>ultimo_hodometro_veiculo · ultimo_hodometro_veiculo_interno</code></td><td>RPC</td><td>A pública devolve vazio; a interna, sem acesso pelos apps, serve à validação do hodômetro</td></tr>\n<tr><td><code>metricas_pdv_dashboard · meu_contexto_pdv</code></td><td>RPC</td><td>Dashboard de fechamento de caixa e contexto da revenda logada</td></tr>\n<tr><td><code>robo_teste_pdv_gerar_leitura_bomba · robo_teste_pdv_gerar_lote_leituras</code></td><td>robô</td><td>Geram leituras de bomba para as empresas de teste</td></tr></tbody></table></div>\n    <dl class=\"elements\">\n      <div class=\"el\"><dt>Separação</dt><dd>Repositório e deploy próprios, sem API: o navegador chama o Supabase direto e as regras ficam em funções do banco, iguais para PDV, PWAs e painel.</dd></div>\n      <div class=\"el\"><dt>Acesso</dt><dd>Perfis <code>posto</code> (gestor), <code>colaborador</code> e <code>caixa</code> (operador do PDV, ver Perfil Caixa). <code>meu_contexto_pdv()</code> descobre a revenda pelo mesmo mecanismo do restante do sistema; sem revenda vinculada, o PDV mostra um aviso e não carrega dados. O login exige MFA (TOTP) como o painel web: sem autenticador cadastrado, a tela <code>/mfa-setup</code> mostra o QR Code; com ele, pede o código de 6 dígitos. Sem confirmar, nenhuma tela abre.</dd></div>\n      <div class=\"el\"><dt>Permissões por tela</dt><dd>Cada tela do PDV (Pré-Pedido, Resgates, Extrato, Pedidos de ajuste, Dashboard, Bicos, Produtos, Terminais) tem uma funcionalidade na matriz <code>permissoes_perfil</code>, a mesma editada em Permissões no painel web. O gestor do posto (perfil <code>posto</code>) tem acesso total e decide, por funcionalidade, o que o colaborador (operador de caixa) usa na sua revenda. Tela desligada some do menu e a URL direta volta para a pista. A operação da pista, a validação e o abastecimento nunca são bloqueados.</dd></div>\n      <div class=\"el\"><dt>Quem decide as permissões</dt><dd>O gestor de frota e o gestor de posto têm acesso total à sua visão e decidem, funcionalidade por funcionalidade, o que os níveis abaixo deles podem usar. A decisão é por empresa, vale na hora e bloqueia de verdade, no menu e na URL direta do painel web, nos PWAs e no PDV. O gestor nunca é travado pela própria personalização. O administrador define só o padrão dos níveis de gestão (Administrador, Gestor de Frota e Posto): não controla o que cada gestor libera a analista e colaborador, e as funcionalidades exclusivas do time interno não aparecem nas matrizes dos gestores. A regra está no banco (políticas de <code>permissoes_perfil</code>), não só na tela.</dd></div>\n      <div class=\"el\"><dt>Fechamento de caixa</dt><dd>O dashboard soma volume, valor e modalidades de pagamento do turno, com filtros por cliente, placa e motorista.</dd></div>\n      <div class=\"el\"><dt>Resgate de pontos</dt><dd>O motorista troca pontos por um benefício do posto e recebe um voucher. O caixa o baixa em <code>/resgates</code>; o valor a receber (campo do benefício, ou pontos x R$ 0,10) fica pendente de acerto e aparece no dashboard.</dd></div>\n      <div class=\"el\"><dt>Orientação de NF-e</dt><dd>Em cada abastecimento confirmado, o PDV mostra os parâmetros de nota fiscal do cliente já resolvidos para o caso, para o caixa emitir a NF-e certa.</dd></div>\n      <div class=\"el\"><dt>Fila de espera</dt><dd>Pedido negado por regra do cliente não trava o caixa: fica em espera num painel no canto da tela, em qualquer página, atualizado a cada 5 s. Quando o gestor libera ou recusa, o painel avisa; o caixa conclui ou dispensa.</dd></div>\n      <div class=\"el\"><dt>Itens em litros</dt><dd>Produtos como o Arla 32 são vendidos por litro, com volume inteiro ou fracionado, e podem ficar restritos ao diesel. A regra é validada no banco, não só na tela.</dd></div>\n      <div class=\"el\"><dt>Menu lateral e tema</dt><dd>O PDV usa o mesmo menu lateral do painel web: logo FNI no topo, busca, grupos (Operação, Indicadores, Cadastros), recolhível e em gaveta no celular. A engrenagem de configurações escolhe tema claro, escuro ou automático.</dd></div>\n      <div class=\"el\"><dt>Pré-Pedido por OTP</dt><dd>Com o parâmetro de uso habilitado, o gestor cria o Pré-Pedido em Parâmetros de uso (placa, paradas, limite em litros ou R$). A Home do PWA do motorista mostra o OTP da parada atual, que muda a cada 30 s, e é só ele que o motorista informa no caixa. O caixa o digita em <code>/pre-pedido</code>, vê o limite e é levado à pista (banner com placa e limite), onde escolhe a bomba; o abastecimento nasce vinculado, sem código de abastecimento nem OTP extra. Acima do limite, a conclusão é recusada de vez, sem ir ao gestor. Ao queimar a parada, a próxima da rota recebe um novo código e uma nova semente. Ao concluir, o PWA do motorista oferece a avaliação do posto, do abastecimento e do frentista/caixa (RPC <code>meu_abastecimento_pre_pedido_a_avaliar</code>), como na jornada Abastecer.</dd></div>\n      <div class=\"el\"><dt>Voucher no grupo econômico</dt><dd>Um voucher emitido para um benefício pode ser baixado por qualquer posto do mesmo grupo econômico do posto dono do benefício; a mensagem de recusa informa o benefício e o parceiro.</dd></div>\n      <div class=\"el\"><dt>Tema nos apps</dt><dd>Painel web, PDV e os dois PWAs seguem o mesmo padrão claro, escuro ou automático. A escolha vale na hora, fica no aparelho e na conta, e acompanha o usuário entre dispositivos.</dd></div>\n      <div class=\"el\"><dt>Negados</dt><dd>Abastecimento que quebra regra do cliente fica aguardando. O gestor decide no painel web, na tela de negados do PWA ou pelo aviso flutuante.</dd></div>\n      <div class=\"el\"><dt>Pedido de ajuste</dt><dd>Posto e cliente podem pedir a correção de qualquer campo de um abastecimento confirmado, com motivo. A outra parte aprova ou recusa: no PDV em Pedidos de ajuste (o pedido nasce no Extrato), no painel web em Pedidos de Ajuste (PDV) e, para o gestor do cliente, no PWA do gestor. Aprovado, a linha é corrigida e o pedido guarda o antes e o depois. A recusa exige motivo. O último pedido fica registrado no próprio abastecimento (<code>ajuste_status</code>, <code>ajuste_motivo</code>, quem decidiu e quando), visível no Extrato do PDV e no detalhe do abastecimento no painel web. Enquanto há pedido pendente, o Extrato mostra o selo &quot;Em ajuste&quot; e não deixa pedir outro (o banco também recusa); depois de recusado, um novo pedido é permitido.</dd></div>\n      <div class=\"el\"><dt>Notificação de pedidos de ajuste</dt><dd>Quem decide (a contraparte de quem pediu) é avisado de quatro formas: bolinha vermelha no menu do painel web e do PDV, aviso flutuante em tempo real (Realtime em <code>pdv_ajustes</code>), banner âmbar na Home do PWA do cliente (abre a tela de decisão no app) e e-mail pela função <code>pdv-ajuste-email</code> para os gestores da outra parte. Quem pediu recebe e-mail quando o pedido é aprovado, recusado ou cancelado. O e-mail é best-effort: falha nele nunca impede o pedido nem a decisão.</dd></div>\n      <div class=\"el\"><dt>Hodômetro anterior oculto</dt><dd>O último hodômetro do veículo é dado de regra de negócio e antifraude: motorista, caixa, colaborador e posto não o veem. A função <code>ultimo_hodometro_veiculo</code> devolve vazio para qualquer app; a validação (maior que o último) roda só no servidor, em <code>iniciar_abastecimento_pdv</code> via função interna sem acesso pelos apps, e o erro não revela o valor. O PDV mostra apenas o hodômetro do abastecimento atual, já validado, no Resumo da venda.</dd></div>\n      <div class=\"el\"><dt>Perfil Caixa</dt><dd>Operador do PDV na revenda, abaixo do posto. O gestor do posto o convida em Minha Equipe (escolhendo Colaborador ou Caixa) e decide em Permissões o que ele usa. O padrão global libera só as 8 telas do PDV e bloqueia todo o resto do painel web; se o Caixa abrir o painel web, o layout do dashboard o redireciona para o PDV (<code>NEXT_PUBLIC_PDV_URL</code>, padrão <code>pdv.fxgestaodefrotasonline.com</code>).</dd></div>\n      <div class=\"el\"><dt>Extrato paginado</dt><dd>O Extrato do PDV mostra 20 abastecimentos por página, com busca por placa, motorista ou código feita no banco, e indicadores (total, confirmados, negados, ticket médio) calculados sobre o filtro inteiro.</dd></div>\n    </dl>\n  </section>\n\n  <section id=\"rotinas\">\n    <div class=\"sec-head\">\n      <span class=\"eyebrow\">Complemento</span>\n      <h2>Rotinas agendadas</h2>\n      <p>As 25 rotinas ativas no <code>pg_cron</code>, agrupadas por onde rodam. Horários convertidos para o horário de Brasília.</p>\n    </div>\n    <div class=\"table-wrap\">\n      <table>\n        <thead><tr><th>Rotina</th><th>Quando</th><th>O que faz</th></tr></thead>\n        <tbody>\n          <tr class=\"grp\"><td colspan=\"3\">No próprio banco (SQL)</td></tr>\n          <tr><td class=\"mono\">robo_abastecimentos_postos</td><td class=\"when\">a cada 6 h</td><td>Gera abastecimentos de demonstração nas duas empresas de teste</td></tr>\n          <tr><td class=\"mono\">robo_abastecimentos_meios_pagamento</td><td class=\"when\">a cada 6 h</td><td>Gera abastecimentos de cartões de frota de demonstração nas duas empresas de teste</td></tr>\n          <tr><td class=\"mono\">robo_notas_fiscais_teste</td><td class=\"when\">a cada 6 h</td><td>Gera notas fiscais fictícias, só para as duas empresas de teste</td></tr>\n          <tr><td class=\"mono\">atualizar_cache_precos_postos</td><td class=\"when\">a cada 6 h</td><td>Recalcula o cache de preços por posto</td></tr>\n          <tr><td class=\"mono\">faturas_postos_robo</td><td class=\"when\">00:00 diário</td><td>Fecha faturas de postos</td></tr>\n          <tr><td class=\"mono\">faturas_fretes_robo</td><td class=\"when\">dia 1, 00:30</td><td>Fecha faturas de fretes do mês</td></tr>\n          <tr><td class=\"mono\">robo_deteccao_acoes_sugeridas</td><td class=\"when\">06:00 diário</td><td>Detecta CNH vencida, posto acima da média, hodômetro fora do padrão e abastecimento fora do PDV sem Pré-Pedido ou acima do limite</td></tr>\n          <tr class=\"grp\"><td colspan=\"3\">Chamando o Web app (/api/cron)</td></tr>\n          <tr><td class=\"mono\">sync-profrotas</td><td class=\"when\">de hora em hora</td><td>Sincroniza abastecimentos da ProFrotas de todas as chaves ativas</td></tr>\n          <tr><td class=\"mono\">atualizar-fipe</td><td class=\"when\">dia 1, 02:00</td><td>Atualiza o valor FIPE dos veículos</td></tr>\n          <tr><td class=\"mono\">gerar-insights-ia</td><td class=\"when\">02:00 diário</td><td>Gera os insights do dia com o Claude</td></tr>\n          <tr><td class=\"mono\">auto-confirmar-fidelidade</td><td class=\"when\">03:00 diário</td><td>Confirma pontos de fidelidade pendentes</td></tr>\n          <tr><td class=\"mono\">conciliacao-automatica</td><td class=\"when\">04:00 diário</td><td>Concilia abastecimentos com faturas</td></tr>\n          <tr><td class=\"mono\">indicar-condutor-automatico</td><td class=\"when\">04:15 diário</td><td>Indica o condutor de multas pelo cruzamento de dados</td></tr>\n          <tr class=\"grp\"><td colspan=\"3\">Chamando Edge Functions</td></tr>\n          <tr><td class=\"mono\">alertas-sla-fretes</td><td class=\"when\">a cada 30 min</td><td>Alerta fretes com SLA em risco</td></tr>\n          <tr><td class=\"mono\">reportar-excedente-*</td><td class=\"when\">01:30 a 01:40</td><td>Informa ao Stripe o uso acima do plano: veículos, postos e empresas do grupo (3 rotinas)</td></tr>\n          <tr><td class=\"mono\">alertas-cadastros-pendentes</td><td class=\"when\">seg 05:00</td><td>E-mail semanal de cadastros incompletos</td></tr>\n          <tr><td class=\"mono\">alertas-duplicidade-placas</td><td class=\"when\">seg 05:15</td><td>E-mail semanal de placas duplicadas no grupo</td></tr>\n          <tr><td class=\"mono\">alertas-documentos-pendentes</td><td class=\"when\">05:30 diário</td><td>E-mail de documentos de empresas pendentes</td></tr>\n          <tr><td class=\"mono\">alertas-vencimentos</td><td class=\"when\">05:45 diário</td><td>E-mail de CNH, ASO, toxicológico e apólices vencendo</td></tr>\n          <tr><td class=\"mono\">email-trials</td><td class=\"when\">06:00 diário</td><td>E-mails da jornada de teste grátis</td></tr>\n          <tr><td class=\"mono\">atualizar-precos-anp</td><td class=\"when\">seg 06:00 e ter 09:00</td><td>Importa preços da ANP, com segunda tentativa de segurança (2 rotinas)</td></tr>\n          <tr><td class=\"mono\">atualizar-postos-anp</td><td class=\"when\">ter 10:00</td><td>Atualiza o cadastro de postos da ANP</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <section id=\"achados\">\n    <div class=\"sec-head\">\n      <span class=\"eyebrow\">Diagnóstico</span>\n      <h2>Achados da arquitetura</h2>\n      <p>O que o levantamento mostrou, do mais urgente para o menos urgente, e o que já está bem resolvido.</p>\n    </div>\n    <div class=\"findings\">\n      <div class=\"f\"><span class=\"sev sev-alta\">Alta</span><div>\n        <h3>Aplicação em Singapura, banco em São Paulo <span class=\"status\">Resolvido em 01/10</span></h3>\n        <p>Os três serviços ativos rodam na região <code>asia-southeast1</code> do Railway, e o Supabase está em <code>sa-east-1</code>. Cada consulta atravessa o planeta: nos logs, até a consulta mais simples (<code>perfil_usuario_atual</code>) leva cerca de 290 ms, e uma abertura da tela de abastecimentos levou 6,8 s.</p>\n        <p class=\"acao\">Feito: os três serviços foram movidos para <code>us-east4</code> (Virgínia), a região do Railway mais próxima do Brasil, sem tempo fora do ar. A consulta do índice de preços caiu de 400 a 1.450 ms para 210 a 250 ms.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-alta\">Alta</span><div>\n        <h3>Legado Python exposto e sem uso <span class=\"status pend\">Aguardando aprovação no Railway</span></h3>\n        <p><code>api.fxgestaodefrotasonline.com</code> publica a documentação Swagger e recebe varreduras automáticas (hoje, tentativas de ler <code>.git-credentials</code>). <code>app.</code> roda o Streamlit antigo com chaves do Stripe, Anthropic e Resend nas variáveis. Nas últimas 24 h nenhum dos dois teve tráfego de usuário.</p>\n        <p class=\"acao\">Feito: o PWA do gestor não chama mais a API antiga. As 10 telas antigas e os serviços que a usavam foram removidos, e a tela Veículos, que já era do Supabase, ganhou atualização ao vivo. Falta só desligar os dois serviços no Railway.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-media\">Média</span><div>\n        <h3>Serviços órfãos no Railway <span class=\"status pend\">Aguardando aprovação no Railway</span></h3>\n        <p>Há uma cópia do Streamlit sem domínio (projeto <code>generous-acceptance</code>), um serviço com deploy falhando desde junho (<code>alert-expression</code>) e dois bancos Postgres em projetos antigos (<code>responsible-laughter</code> e <code>lavish-enthusiasm</code>).</p>\n        <p class=\"acao\">Ação: revisar e remover para reduzir custo e superfície de ataque.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-media\">Média</span><div>\n        <h3>Edge Functions temporárias <span class=\"status\">Sem risco</span></h3>\n        <p><code>temp-criar-meter-posto</code>, <code>temp-criar-produtos-grupo-frota</code> e <code>temp-teste-conectividade-anp</code> seguem publicadas, mas o código das três já foi trocado por uma resposta 410 sem efeito. A remoção é só limpeza, pelo painel do Supabase.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-media\">Média</span><div>\n        <h3>Robôs de dados rodando em produção <span class=\"status\">Resolvido em 01/10</span></h3>\n        <p>Os robôs de abastecimento já eram restritos às duas empresas de teste, mas sorteavam o horário até 23:55 do dia, gravando registros no futuro. Não era fuso da ProFrotas. O robô de notas fiscais de teste não tinha restrição de empresa.</p>\n        <p class=\"acao\">Feito: os robôs agora sorteiam até o momento da execução, e o de notas ficou restrito às empresas de teste. As definições antigas estão salvas em <code>_backup_funcoes_robos</code>.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-baixa\">Baixa</span><div>\n        <h3>Cobrança de clientes e emissão fiscal simuladas</h3>\n        <p>As camadas <code>lib/cobranca</code> (Asaas, Cora) e <code>lib/fiscal</code> (Focus NFe, PlugNotas) já têm a interface pronta, mas só o provedor simulado está implementado. O Pix é real. O Stripe cobre apenas as assinaturas do próprio FNI.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-baixa\">Baixa</span><div>\n        <h3>Configuração obsoleta <span class=\"status\">Resolvido em 01/10</span></h3>\n        <p><code>vercel.json</code> ainda declara o cron da ProFrotas, que hoje roda pelo <code>pg_cron</code>. Removido do repositório.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-media\">Média</span><div>\n        <h3>PDV sem tela para ver as avaliações <span class=\"status pend\">Pendente</span></h3>\n        <p>As notas dadas pelo motorista são gravadas em <code>avaliacoes_abastecimento_pdv</code>, mas nenhuma tela mostra esses dados ao posto ou ao gestor.</p>\n        <p class=\"acao\">Ação: criar uma visão de avaliações no PDV e no painel da revenda.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-baixa\">Baixa</span><div>\n        <h3>Pedido de ajuste de abastecimento PDV <span class=\"status\">Resolvido em 05/10</span></h3>\n        <p>Posto e cliente pedem, a outra parte aprova ou recusa (recusa com motivo registrado no abastecimento), com notificação em tempo real e por e-mail. Desde 06/10 o PWA do cliente também decide o pedido pelo app (aprovar ou recusar com motivo).</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-baixa\">Baixa</span><div>\n        <h3>Leituras de bomba vêm de robô <span class=\"status\">Esperado na fase piloto</span></h3>\n        <p>As leituras que o PDV oferece hoje são geradas por <code>robo_teste_pdv_*</code> para empresas de teste. A integração com a bomba real (automação do posto) ainda não existe.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-media\">Média</span><div>\n        <h3>PDV nasceu em Singapura <span class=\"status\">Resolvido em 03/10</span></h3>\n        <p>O novo serviço foi criado na região padrão do Railway (<code>asia-southeast1</code>), repetindo o problema de latência já visto nos outros apps.</p>\n        <p class=\"acao\">Feito: movido para <code>us-east4</code> e verificação de saúde em <code>/login</code>; novo deploy concluído.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-media\">Média</span><div>\n        <h3>Valor a receber dos resgates sem tela de acerto <span class=\"status pend\">Pendente</span></h3>\n        <p>Cada voucher baixado grava <code>valor_a_receber</code> e <code>acerto_status</code> = pendente, mas nenhuma tela permite conciliar ou marcar como liquidado.</p>\n        <p class=\"acao\">Ação: criar a visão de acerto entre posto, FNI e cliente.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-baixa\">Baixa</span><div>\n        <h3>Orientação de NF depende da UF do posto <span class=\"status pend\">Atenção</span></h3>\n        <p>Na regra \"CNPJ por Estado\", o destino usa a UF cadastrada na empresa do posto. Sem UF, o PDV cai no CNPJ padrão da regra.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-baixa\">Baixa</span><div>\n        <h3>Fila de espera atualizada por consulta <span class=\"status pend\">Pendente</span></h3>\n        <p>O painel de espera consulta o banco a cada 5 segundos em cada caixa aberto. Funciona, mas o Realtime já usado em outros pontos reduziria o tráfego e daria aviso imediato.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-baixa\">Baixa</span><div>\n        <h3>Pré-Pedido fora do PDV só avisa <span class=\"status\">Tratado em parte</span></h3>\n        <p>A recusa de abastecimento acima do limite continua só no PDV (<code>avaliar_regras_abastecimento_pdv</code>). Nos outros canais (integração, planilha, lançamento manual) o abastecimento já aconteceu, então o robô diário gera uma Ação Sugerida de aviso, sem bloquear.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-baixa\">Baixa</span><div>\n        <h3>Modo escuro dos PWAs sem revisão visual <span class=\"status pend\">Pendente</span></h3>\n        <p>As cores fixas dos PWAs (cerca de mil no do gestor) foram trocadas em massa por cores que mudam com o tema, validadas só por análise de código. Mapas, imagens e listas de cores constantes seguem no claro.</p>\n        <p class=\"acao\">Ação: percorrer as telas principais nos dois temas e ajustar o que ficar ilegível.</p>\n      </div></div>\n      <div class=\"f\"><span class=\"sev sev-forte\">Ponto forte</span><div>\n        <h3>Segurança e automação no banco</h3>\n        <p>As 192 tabelas têm RLS, o que vale para o Web app, os PWAs, a API de integrações e até o assistente IA. A automação está centralizada no <code>pg_cron</code>, com registro de cada consulta e duração no Web app.</p>\n      </div></div>\n    </div>\n  </section>\n\n  <section id=\"historico\">\n    <div class=\"sec-head\">\n      <span class=\"eyebrow\">Revisões de 1 e 3 de outubro de 2026</span>\n      <h2>Histórico de ajustes</h2>\n      <p>O que mudou na arquitetura desde o levantamento, na ordem em que foi feito.</p>\n    </div>\n    <div class=\"table-wrap\">\n      <table>\n        <thead><tr><th>Ajuste</th><th>Onde</th><th>Resultado</th></tr></thead>\n        <tbody>\n          <tr class=\"grp\"><td colspan=\"3\">6 de outubro de 2026 · Ajustes no app, Caixa e documentação</td></tr>\n          <tr><td>Avaliação do motorista no Pré-Pedido: ao concluir, a Home abre a avaliação de posto, abastecimento e frentista/caixa, e o cartão fica 24 h se ele dispensar</td><td class=\"when\">estrada-que-cuida (Home) · RPC <code>meu_abastecimento_pre_pedido_a_avaliar</code></td><td>Reaproveita <code>avaliar_abastecimento_pdv</code> e a tela de avaliação da jornada Abastecer</td></tr>\n          <tr><td>Pedido de ajuste decidido direto no PWA Cliente: lista com antes e depois, Aprovar e Recusar (motivo obrigatório), bolinha no menu e banner que abre a tela do app</td><td class=\"when\">estudo-de-rede (<code>features/ajustes_pdv</code>)</td><td>Usa as RPCs <code>meus_ajustes_pdv</code> e <code>decidir_ajuste_pdv</code>; nenhuma regra nova no banco</td></tr>\n          <tr><td>Caixa que abre o painel web é redirecionado ao PDV; colaborador antigo de cliente convertido em Analista</td><td class=\"when\">Web app (layout do dashboard) · <code>usuarios_app</code></td><td>Padrão do Caixa já bloqueava o resto do painel</td></tr>\n          <tr><td>Documentação técnica (arquitetura e funcional/APIs) publicada em <code>/documentacao</code>, com senha, MFA e perfil admin</td><td class=\"when\">Web app (<code>/documentacao</code>) · Mermaid hospedado em <code>/vendor</code></td><td>Link no rodapé da landing; outros perfis recebem 403</td></tr>\n          <tr class=\"grp\"><td colspan=\"3\">5 de outubro de 2026 · Pedidos de ajuste, perfis e PDV</td></tr>\n          <tr><td>Recusa de pedido de ajuste exige motivo e fica registrada no abastecimento (status, motivo, quem e quando), com preenchimento do histórico existente</td><td class=\"when\">pdv-fni (Extrato e Pedidos de ajuste) · Web app (detalhe do abastecimento PDV e Pedidos de Ajuste) · migration <code>pdv_ajuste_registro_no_abastecimento_e_motivo_recusa_obrigatorio</code></td><td>Selo &quot;Ajuste recusado&quot; e motivo no Extrato; o último pedido aparece no detalhe</td></tr>\n          <tr><td>Notificação de pedidos de ajuste: bolinha no menu, aviso flutuante em tempo real, banner no PWA do cliente e e-mail ao decisor e, na decisão, a quem pediu</td><td class=\"when\">Web app · pdv-fni · estudo-de-rede · Edge Function <code>pdv-ajuste-email</code> · migrations <code>pdv_ajustes_notificacao_contagem_e_realtime</code> e <code>pdv_ajustes_trigger_email</code></td><td>Antes, o gestor só descobria o pedido abrindo a tela</td></tr>\n          <tr><td>Extrato do PDV: paginação (20 por página), busca no banco e selo &quot;Em ajuste&quot; que bloqueia novo pedido enquanto há um pendente</td><td class=\"when\">pdv-fni (<code>/extrato</code>)</td><td>Acabou o limite de 100 linhas; indicadores cobrem o filtro inteiro</td></tr>\n          <tr><td>Hodômetro anterior oculto de motorista, caixa, colaborador e posto; validação só no servidor; Resumo da venda mostra o hodômetro já validado do abastecimento atual</td><td class=\"when\">estrada-que-cuida · pdv-fni · migration <code>hodometro_anterior_oculto_do_motorista_e_posto</code></td><td>Texto &quot;último registrado&quot;, botão de usar o último e pré-preenchimento saíram dos apps do motorista</td></tr>\n          <tr><td>Perfil Caixa no posto: convidado em Minha Equipe, padrão com as 8 telas do PDV liberadas e o resto do painel bloqueado, editável pelo gestor do posto</td><td class=\"when\">Web app · migration <code>perfil_caixa_pdv_posto</code></td><td>Permissões do posto passam a ter colunas Colaborador e Caixa; item Permissões entrou no menu do posto</td></tr>\n          <tr><td>Equipe do cliente entra como Analista; o analista perdeu os poderes globais (usuários, leitura global, badges); na visão do cliente o gestor decide só o Analista</td><td class=\"when\">Web app · migration <code>analista_so_do_cliente_sem_poderes_globais</code></td><td>Antes, analista era perfil do time FNI</td></tr>\n          <tr><td>Permissões com nome, grupo e descrição detalhada por funcionalidade, selo &quot;Atenção&quot; nas sensíveis; 97 funcionalidades na matriz</td><td class=\"when\">Web app (<code>permissoesCatalogo.ts</code>)</td><td>Rótulos técnicos como &quot;Aba: Ajustes Pdv&quot; foram substituídos</td></tr>\n          <tr><td>Parâmetros de uso: filtros por placa, motorista e status em todas as abas</td><td class=\"when\">Web app (<code>/parametros-uso</code>)</td><td>Cada aba mostra só os filtros que fazem sentido</td></tr>\n          <tr><td>Atualização de postos da ANP passa a gravar <code>atualizado_em</code> em cada posto processado</td><td class=\"when\">Edge Function <code>atualizar-postos-anp</code> (v2) · migration <code>anp_postos_atualizado_em</code></td><td>Permite provar pelo banco que a rotina de terça rodou</td></tr>\n          <tr class=\"grp\"><td colspan=\"3\">5 de outubro de 2026 · Segurança e permissões</td></tr>\n          <tr><td>MFA (TOTP) obrigatório no PDV FNI, igual ao painel web: cadastro do autenticador por QR Code e código de 6 dígitos a cada novo login</td><td class=\"when\">pdv-fni (<code>/mfa-setup</code> e gate no layout)</td><td>Sem aal2, nenhuma tela do PDV abre; os postos precisarão cadastrar o autenticador no primeiro acesso</td></tr>\n          <tr><td>Permissões: o gestor de frota e o de posto decidem o que os níveis abaixo podem usar, com bloqueio real por empresa (menu, URL, PWAs e PDV); o admin deixou de controlar essa parte e as telas exclusivas do time interno saíram das matrizes dos gestores</td><td class=\"when\">Web app · pdv-fni · estudo-de-rede · migrations <code>permissoes_gestor_delega_apenas_niveis_abaixo_e_colaborador_pdv</code>, <code>permissoes_admin_nao_controla_niveis_inferiores_dos_gestores</code> e <code>permissoes_funcionalidades_exclusivas_do_admin_e_bicos_do_posto</code></td><td>Antes, a personalização da empresa não bloqueava ninguém e o aviso na tela dizia isso. Agora bloqueia; gestores nunca são travados</td></tr>\n          <tr><td>Revisão geral das permissões: 13 funcionalidades novas na matriz (Abastecimentos Negados, Pedidos de Ajuste, Abastecimentos Sem Motorista, Jornada dos Motoristas, Formas de Pagamento do PDV, Dashboard do PDV, Bicos do PDV e 6 telas do app PDV), seed para os cinco perfis</td><td class=\"when\">Web app · pdv-fni · estudo-de-rede · migration <code>permissoes_funcionalidades_pdv_ajustes_negados_e_outras</code></td><td>Telas do PDV deixaram de dividir \"Abastecimentos\"; agora a matriz tem 93 funcionalidades. O PDV filtra menu e rotas por ela</td></tr>\n          <tr class=\"grp\"><td colspan=\"3\">4 de outubro de 2026 · PDV FNI e Pré-Pedido</td></tr>\n          <tr><td>Pré-Pedido fora do PDV: aviso nas Ações Sugeridas quando um abastecimento de integração, planilha ou lançamento manual vem sem Pré-Pedido ou acima do limite</td><td class=\"when\">Web app · migrations <code>acoes_sugeridas_pre_pedido_excedido_outros_canais</code> e <code>executar_acao_pre_pedido_excedido_ciente</code></td><td>Só avisa; o gestor dá ciência. Entra no robô diário das 06:00</td></tr>\n          <tr><td>Pedido de ajuste de abastecimento PDV, pedido por posto ou cliente e aprovado pela contraparte, qualquer campo, com a correção registrada</td><td class=\"when\">pdv-fni (Extrato e Pedidos de ajuste) · Web app (Pedidos de Ajuste) · migrations <code>pdv_pedido_de_ajuste_com_aprovacao_da_contraparte</code> e <code>pdv_ajuste_guarda_originais_dos_valores_derivados</code></td><td>Linha corrigida com marca do pedido; diferença de pontos lançada no extrato do motorista</td></tr>\n          <tr><td>Modo escuro: balão do chat do frete, assinatura do canhoto e status de resgate legíveis no PWA do motorista; cartões da Visão Geral e selo de emergência no PWA do gestor</td><td class=\"when\">estrada-que-cuida · estudo-de-rede</td><td>Revisão por código; falta conferir tela por tela</td></tr>\n          <tr class=\"grp\"><td colspan=\"3\">3 de outubro de 2026 · PDV FNI</td></tr>\n          <tr><td>Pré-Pedido seguro: o motorista informa só o OTP rotativo (30 s) mostrado na Home do PWA; o caixa não digita mais o código fixo, escolhe a bomba na pista e o abastecimento nasce vinculado, sem pedir código nem OTP de novo. Deixou de vincular abastecimento sozinho</td><td class=\"when\">pdv-fni · estrada-que-cuida · Web app · migrations <code>pdv_consultar_pre_pedido_nao_vincula_sozinho</code>, <code>pdv_iniciar_abastecimento_por_pre_pedido_sem_codigo_otp</code>, <code>pre_pedido_otp_rotativo_no_pwa_motorista</code> e <code>consultar_pre_pedido_para_posto_por_otp</code></td><td>Código visto por terceiros não libera abastecimento; só o OTP do momento vale</td></tr>\n          <tr><td>Tela Pré-Pedido no caixa: código de 6 dígitos, autorização por 60 min, vínculo automático ao abastecimento e recusa definitiva acima do limite</td><td class=\"when\">pdv-fni · estrada-que-cuida · migration <code>pdv_pre_pedido_autorizacao_no_caixa_e_bloqueio_de_limite</code></td><td>Novo item de menu em Operação; app do motorista explica a recusa por limite</td></tr>\n          <tr><td>Pré-Pedido manual: criação em Parâmetros de uso, limite por parada em litros ou R$, código aleatório de 6 dígitos por parada, campo no PDV e card na Home do PWA do motorista</td><td class=\"when\">Web app · pdv-fni · estrada-que-cuida · migrations <code>pre_pedido_manual_com_limite_e_numero_no_pdv</code>, <code>meus_pre_pedidos_motorista</code> e <code>pre_pedido_codigo_aleatorio_6_digitos_por_parada</code></td><td>Ao queimar a parada, a próxima da rota recebe novo código; pré-pedido conclui quando todas são atendidas</td></tr>\n          <tr><td>Tema claro, escuro ou automático nos dois PWAs, ligado à conta</td><td class=\"when\">estrada-que-cuida · estudo-de-rede · migration <code>tema_preferido_motoristas_e_obter_tema</code></td><td>Mesmo padrão do painel web; tokens de cor adaptativos e item de tema no menu</td></tr>\n          <tr><td>Menu lateral no PDV, com logo FNI, e configurações de tema</td><td class=\"when\">pdv-fni</td><td>Substitui o cabeçalho no topo pela estrutura de menu do painel web</td></tr>\n          <tr><td>Voucher aceito por postos do mesmo grupo econômico e mensagem de recusa com o benefício</td><td class=\"when\">migrations <code>voucher_aceita_postos_do_mesmo_grupo_economico</code> e <code>voucher_validar_outro_beneficiario_informa_beneficio</code></td><td>Cashier não vê mais o valor a receber</td></tr>\n          <tr><td>Indicador de cliente atual do painel passou a guardar o último cliente ao navegar por drill-down</td><td class=\"when\">Web app · <code>IndicadorClienteAtual</code></td><td>Some o aviso &quot;Nenhum cliente selecionado&quot; indevido</td></tr>\n          <tr><td>Resgate de pontos no PDV: tela <code>/resgates</code>, queima com terminal e valor a receber, indicadores no dashboard</td><td class=\"when\">pdv-fni · migration <code>pdv_resgate_voucher_queima_e_valor_a_receber</code></td><td>Web do posto passa a usar a mesma RPC de queima</td></tr>\n          <tr><td>Orientação de emissão da NF-e no extrato e no comprovante</td><td class=\"when\">pdv-fni · <code>parametros_nf_abastecimento_pdv</code></td><td>Parâmetros de NF do cliente resolvidos por abastecimento</td></tr>\n          <tr><td>Fila de espera para abastecimentos pendentes de liberação</td><td class=\"when\">pdv-fni · migration <code>pdv_fila_de_espera_abastecimentos_pendentes_liberacao</code></td><td>Caixa segue atendendo; aviso e bipe quando o gestor decide; 10 min de folga após liberar</td></tr>\n          <tr><td>Itens em litros com volume fracionado e regra &quot;só diesel&quot; (Arla)</td><td class=\"when\">pdv-fni · migration <code>pdv_itens_fracionados_arla_unidade_e_somente_diesel</code></td><td>Validado em <code>concluir_abastecimento_pdv</code>; extrato e dashboard mostram litros</td></tr>\n          <tr><td>Publicação do PDV FNI com domínio <code>pdv.fxgestaodefrotasonline.com</code> e ícone da marca</td><td class=\"when\">Railway · Cloudflare</td><td>Qualquer navegador acessa; login com a conta <code>posto</code></td></tr>\n          <tr><td>PDV movido de Singapura para <code>us-east4</code></td><td class=\"when\">Railway</td><td>Mesma região dos outros apps</td></tr>\n          <tr><td>Redesenho visual de bombas, bicos, extrato, produtos e terminais</td><td class=\"when\">pdv-fni</td><td>Telas no mesmo padrão visual, mais rápidas para o frentista</td></tr>\n          <tr><td>Dashboard de fechamento de caixa</td><td class=\"when\">pdv-fni · <code>metricas_pdv_dashboard</code></td><td>Volume, valor e modalidades, com filtros por cliente, placa e motorista</td></tr>\n          <tr><td>Liberação de abastecimentos negados</td><td class=\"when\">Web, PWA do gestor e banco</td><td>Gestor decide por tela, badge e aviso; motorista acompanha por RPC</td></tr>\n          <tr><td>Tela de avaliação do posto no PWA do motorista</td><td class=\"when\">estrada-que-cuida · <code>avaliar_abastecimento_pdv</code></td><td>Três notas por estrelas, observação opcional e nome do posto</td></tr>\n          <tr><td>Parâmetros de uso editáveis (9 tipos)</td><td class=\"when\">Web app</td><td>Antes só dava para inativar ou excluir</td></tr>\n          <tr class=\"grp\"><td colspan=\"3\">1 de outubro de 2026 · levantamento inicial</td></tr>\n          <tr><td>Web app e os dois PWAs saíram de Singapura para <code>us-east4</code> (Virgínia)</td><td class=\"when\">Railway</td><td>Sem tempo fora do ar. Consulta do índice de preços: de 400 a 1.450 ms para 210 a 250 ms</td></tr>\n          <tr><td>Robôs de demonstração passaram a sortear horário só até o momento da execução</td><td class=\"when\">Supabase · migration <code>robos_dados_teste_sem_data_futura_e_escopo</code></td><td>Fim dos abastecimentos gravados no futuro. Versões antigas em <code>_backup_funcoes_robos</code></td></tr>\n          <tr><td>Robô de notas fiscais fictícias restrito às empresas de teste</td><td class=\"when\">Supabase · mesma migration</td><td>Um cliente real nunca recebe nota de teste</td></tr>\n          <tr><td>Remoção do <code>vercel.json</code> obsoleto</td><td class=\"when\">gestao-frotas-web · <code>99bd20a</code></td><td>Agendamento documentado num lugar só: <code>pg_cron</code></td></tr>\n          <tr><td>Veículos ao vivo no PWA do gestor e remoção de 15 arquivos da API legada</td><td class=\"when\">estudo-de-rede · <code>2f32094</code></td><td>Nenhum app depende mais de <code>api.</code>; análise e build Flutter sem erros</td></tr>\n          <tr><td>Edge Functions temporárias revisadas</td><td class=\"when\">Supabase</td><td>Já respondiam 410 sem efeito; remoção pelo painel é só limpeza</td></tr>\n          <tr class=\"grp\"><td colspan=\"3\">Pendente de aprovação no Railway</td></tr>\n          <tr><td>Desligar <code>app.</code> e <code>api.</code></td><td class=\"when\">Railway</td><td>Sem dependentes; aprovado por você, exclusão recusada na janela de confirmação</td></tr>\n          <tr><td>Remover serviços órfãos e os dois bancos antigos</td><td class=\"when\">Railway</td><td>Mesma situação</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <footer>Modelo C4 de Simon Brown: contexto, containers, componentes e código. Contagens extraídas dos repositórios e do banco em 5 de outubro de 2026 (373 funções, 192 tabelas).</footer>\n</div>\n\n</body></html>";
